# MOH Coop Trilogy - SERVER HOST GUI ("MOH Coop Server" desktop shortcut).
#
# Hosts the HZM coop mod as a DEDICATED server (omohaaded.exe, headless) or HOST-AND-PLAY (a listen server inside your
# own game, openmohaa.exe). Every gameplay setting comes from hzm_server_settings.json, the catalogue GENERATED by
# docs/tools/gen_server_catalogue.py (docgen.py build) from the mod's cvar sweep - nothing here lists cvars by hand.
#
#   hzm_server_gui.ps1                         the window (normally via hzm_server_gui.vbs, no console)
#   hzm_server_gui.ps1 -StartProfile <profile> the window on that profile, its server started (start-with-Windows,
#                                              "open the window" choice)
#   hzm_server_gui.ps1 -Supervise <profile>    headless server supervisor: start, restart on crash, daily restart,
#                                              rotation, Discord webhook, MOTD. The GUI starts one per running profile
#                                              through WMI (bug-11282: a child of a shell dies with the shell's job).
#   -Snapshot <dir> [-SnapshotDpi 144]         QA: render every tab to PNG off-screen (never activated) and exit
#   -DryRun                                    firewall / UPnP / start-with-Windows are written to dryrun_actions.log
#                                              and never executed
#   -NoUi                                      define the functions only (dot-sourced by tests)
#
# Lives beside openmohaa.exe / omohaaded.exe (shipped by the updater, publish_release.ps1). Profiles, logs and the
# DPAPI-protected secrets (passwords, webhook) live in %LOCALAPPDATA%\MOHCoopServer. Secrets are never logged.
# Windows PowerShell 5.1 + WPF only: nothing for a player to install.
param(
    [string]$InstallRoot = $PSScriptRoot,
    [string]$DataDir = (Join-Path $env:LOCALAPPDATA "MOHCoopServer"),
    [string]$Catalogue = "",
    [string]$Supervise = "",
    [string]$StartProfile = "",
    [string]$Snapshot = "",
    [int]$SnapshotDpi = 96,
    [int]$SnapshotWidth = 1100,
    [int]$SnapshotHeight = 720,
    [switch]$DryRun,
    [switch]$NoUi,
    [string]$SpeedTestUrl = "https://speed.cloudflare.com/__up",
    [string]$PublicIpUrl = "https://api.ipify.org"
)
$ErrorActionPreference = "Continue"
$script:Version = "1.0.0"
$script:GuiPath = $MyInvocation.MyCommand.Path      # also right when dot-sourced (-NoUi tests)
$script:GuiDir = Split-Path -Parent $script:GuiPath
try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}

# ======================================================================================================================
# basics: folders, log (never secrets), DPAPI secrets
# ======================================================================================================================
foreach ($d in @($DataDir, (Join-Path $DataDir "profiles"), (Join-Path $DataDir "run"), (Join-Path $DataDir "logs"))) {
    if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Force -Path $d | Out-Null }
}
$script:GuiLog = Join-Path $DataDir "gui.log"
$script:SecretWords = New-Object System.Collections.Generic.List[string]

function Write-Log([string]$msg, [string]$file = $script:GuiLog) {
    # every log line passes through the secret scrubber: a password or webhook that reaches a message is masked
    foreach ($w in $script:SecretWords) { if ($w -and $w.Length -ge 3) { $msg = $msg.Replace($w, "****") } }
    $msg = [regex]::Replace($msg, 'https://(discord|discordapp)\.com/api/webhooks/\S+', 'https://discord.com/api/webhooks/****')
    try { Add-Content -LiteralPath $file -Value ("{0:yyyy-MM-dd HH:mm:ss} {1}" -f (Get-Date), $msg) -Encoding UTF8 } catch {}
}
function Write-DryRun([string]$what) {
    Write-Log "DRY RUN - not executed: $what" (Join-Path $DataDir "dryrun_actions.log")
}

Add-Type -AssemblyName System.Security
function Protect-Text([string]$s) {
    $b = [Text.Encoding]::UTF8.GetBytes($s)
    [Convert]::ToBase64String([Security.Cryptography.ProtectedData]::Protect($b, $null, 'CurrentUser'))
}
function Unprotect-Text([string]$s) {
    try {
        $b = [Security.Cryptography.ProtectedData]::Unprotect([Convert]::FromBase64String($s), $null, 'CurrentUser')
        [Text.Encoding]::UTF8.GetString($b)
    } catch { "" }
}
function New-RandomPassword([int]$n = 20) {
    $chars = 'abcdefghijkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    $rng = [Security.Cryptography.RandomNumberGenerator]::Create()
    $bytes = New-Object byte[] $n; $rng.GetBytes($bytes)
    -join ($bytes | ForEach-Object { $chars[$_ % $chars.Length] })
}

# ======================================================================================================================
# install detection
# ======================================================================================================================
function Get-Install {
    $gs = Get-GuiSettings
    $root = if ($gs.installRoot) { $gs.installRoot } else { $InstallRoot }
    $base = $gs.basePath; $homeDir = $gs.homePath
    if (-not $base) {
        $info = Join-Path $root "install_info.txt"
        if (Test-Path -LiteralPath $info) {
            $m = Select-String -LiteralPath $info -Pattern "^GogPath=(.*)$"
            if ($m) { $base = $m.Matches[0].Groups[1].Value.Trim() }
        }
    }
    $launchArgs = ""
    $ini = Join-Path $root "updater.ini"
    if (Test-Path -LiteralPath $ini) {
        foreach ($l in Get-Content -LiteralPath $ini) { if ($l -match '^LaunchArgs=(.*)$') { $launchArgs = $Matches[1].Trim() } }
    }
    if (-not $base -and $launchArgs -match 'fs_basepath "([^"]+)"') { $base = $Matches[1] }
    if (-not $homeDir -and $launchArgs -match 'fs_homepath "([^"]+)"') { $homeDir = $Matches[1] }
    if (-not $homeDir) { $homeDir = Join-Path $root "home" }
    if (-not $base) { $base = $root }
    [pscustomobject]@{
        Root = $root; Base = $base; Home = $homeDir; LaunchArgs = $launchArgs
        Ded = Join-Path $root "omohaaded.exe"; Client = Join-Path $root "openmohaa.exe"
        Maintt = Join-Path $homeDir "maintt"; Updater = Join-Path $root "updater.ps1"
    }
}
function Get-GuiSettings {
    $p = Join-Path $DataDir "gui_settings.json"
    $o = [pscustomobject]@{ installRoot = ""; basePath = ""; homePath = ""; lastProfile = "Default" }
    if (Test-Path -LiteralPath $p) {
        try { $j = Get-Content -LiteralPath $p -Raw | ConvertFrom-Json; foreach ($k in $o.PSObject.Properties.Name) { if ($j.$k) { $o.$k = $j.$k } } } catch {}
    }
    $o
}
function Save-GuiSettings($o) { $o | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $DataDir "gui_settings.json") -Encoding UTF8 }

# ======================================================================================================================
# the generated catalogue
# ======================================================================================================================
function Import-Catalogue {
    $cands = @()
    if ($Catalogue) { $cands += $Catalogue }
    $cands += (Join-Path $InstallRoot "hzm_server_settings.json")
    $cands += (Join-Path $PSScriptRoot "hzm_server_settings.json")
    $cands += (Join-Path $PSScriptRoot "..\..\docs\generated\server_settings.json")   # running from the dev tree
    foreach ($c in $cands) {
        if ($c -and (Test-Path -LiteralPath $c)) {
            Add-Type -AssemblyName System.Web.Extensions
            $js = New-Object System.Web.Script.Serialization.JavaScriptSerializer
            $js.MaxJsonLength = 64MB
            $cat = $js.DeserializeObject([IO.File]::ReadAllText((Resolve-Path -LiteralPath $c).Path))
            $cat["_path"] = (Resolve-Path -LiteralPath $c).Path
            $byName = @{}
            foreach ($e in $cat["settings"]) { $byName[$e["name"].ToLower()] = $e }
            $cat["_byName"] = $byName
            return $cat
        }
    }
    throw "hzm_server_settings.json not found beside the GUI - run the MOH Coop Trilogy shortcut once so the updater can fetch it."
}

# ======================================================================================================================
# profiles
# ======================================================================================================================
function New-Profile([string]$name, [int]$port = 12203) {
    [pscustomobject]@{
        name = $name; mode = "dedicated"; hostname = "^3MOH ^7Coop ^2Server"; port = $port; queryPort = $port + 97
        maxPlayers = 4; public = $false; missionMode = "campaign"; map = "m1l1"; rotation = @(); settings = @{}
        affinity = @(); priority = "AboveNormal"; autoRestart = $true; dailyRestart = ""; startWithWindows = $false
        # how start-with-Windows starts it: "hidden" = the supervisor alone (no window), "window" = this window opens on
        # the profile and starts its server. A profile saved before the field existed reads "hidden", as it ran then.
        startupMode = "hidden"
        motd = ""; motdRepeatMin = 0; hookUp = $true; hookDown = $true; hookJoin = $true; hookLeave = $true
        logKeepDays = 14; bans = @(); whitelist = @(); whitelistOn = $false; updateOnStart = $false
        lightGraphics = "auto"; upnp = $false
        # match recording: the engine's server recorder (sv_demo.c) - sv_autoRecord = one demo per map, every player
        # and AI on it; the engine keeps sv_autoRecordMax files / sv_autoRecordMaxMB in <home>\maintt\demos
        recordMatches = $true; recordMaxFiles = 30; recordMaxMB = 2048
        recordFolder = ""; recordFolderMaxGB = 20; recordFolderMaxDays = 30
    }
}
function Get-ProfileNames {
    @(Get-ChildItem -LiteralPath (Join-Path $DataDir "profiles") -Filter "*.json" -File -ErrorAction SilentlyContinue |
        ForEach-Object { $_.BaseName } | Sort-Object)
}
function Test-ProfileName([string]$n) { $n -match '^[A-Za-z0-9 _-]{1,32}$' }
function Read-Profile([string]$name) {
    $p = New-Profile $name
    $f = Join-Path $DataDir "profiles\$name.json"
    if (Test-Path -LiteralPath $f) {
        try {
            $j = Get-Content -LiteralPath $f -Raw | ConvertFrom-Json
            foreach ($k in $p.PSObject.Properties.Name) {
                if ($null -ne $j.PSObject.Properties[$k]) { $p.$k = $j.$k }
            }
            $h = @{}
            if ($j.settings) { foreach ($q in $j.settings.PSObject.Properties) { $h[$q.Name] = "$($q.Value)" } }
            $p.settings = $h
            $p.rotation = @($j.rotation | Where-Object { $_ }); $p.affinity = @($j.affinity | ForEach-Object { [int]$_ })
            $p.bans = @($j.bans | Where-Object { $_ }); $p.whitelist = @($j.whitelist | Where-Object { $_ })
        } catch { Write-Log "profile $name unreadable: $_" }
    }
    $p
}
function Save-Profile($p) {
    $p | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $DataDir "profiles\$($p.name).json") -Encoding UTF8
}
function Read-Secrets([string]$name) {
    $o = @{ password = ""; rcon = ""; webhook = "" }
    $f = Join-Path $DataDir "profiles\$name.secret"
    if (Test-Path -LiteralPath $f) {
        $t = Unprotect-Text ((Get-Content -LiteralPath $f -Raw).Trim())
        if ($t) { try { $j = $t | ConvertFrom-Json; foreach ($k in @("password", "rcon", "webhook")) { if ($j.$k) { $o[$k] = "$($j.$k)" } } } catch {} }
    }
    foreach ($k in $o.Keys) { if ($o[$k]) { $script:SecretWords.Add($o[$k]) } }
    $o
}
function Save-Secrets([string]$name, $o) {
    $t = ([pscustomobject]$o | ConvertTo-Json -Compress)
    Set-Content -LiteralPath (Join-Path $DataDir "profiles\$name.secret") -Value (Protect-Text $t) -Encoding ascii
    foreach ($k in @("password", "rcon", "webhook")) { if ($o[$k]) { $script:SecretWords.Add($o[$k]) } }
}

# ======================================================================================================================
# the server config the GUI writes (and the command line)
# ======================================================================================================================
function Get-CleanValue([string]$v) {
    # a cfg value can never break out of its quotes or start a second command
    if ($null -eq $v) { return "" }
    ($v -replace '["\r\n;]', '').Trim()
}
function Test-MapName([string]$m) { $m -match '^[A-Za-z0-9_/]{1,64}$' }
# a mission is a map SPEC: the map plus the start tile's own cvars, "m4l0|coop_advTraining=1" (generated catalogue)
function Split-MapSpec([string]$spec) {
    $parts = "$spec" -split '\|'
    $sets = [ordered]@{}
    foreach ($x in ($parts | Select-Object -Skip 1)) {
        if ($x -match '^([A-Za-z_][A-Za-z0-9_]{0,63})=([A-Za-z0-9_.-]{0,64})$') { $sets[$Matches[1]] = $Matches[2] }
    }
    [pscustomobject]@{ Map = $parts[0]; Sets = $sets }
}
function Test-MapSpec([string]$spec) { Test-MapName (Split-MapSpec $spec).Map }
function Test-CvarName([string]$n) { $n -match '^[A-Za-z_][A-Za-z0-9_]{0,63}$' }

function Get-FirstMap($p, $cat) {
    switch ($p.missionMode) {
        "campaign" { return $cat["campaign"]["lobby_map"] }
        "rotation" { if (@($p.rotation).Count) { return @($p.rotation)[0] } }
    }
    if (Test-MapSpec $p.map) { return $p.map }
    "m1l1"
}

function New-ServerCfgText($p, $sec, $cat, [switch]$Listen, [switch]$LightGraphics) {
    $L = New-Object System.Collections.Generic.List[string]
    $L.Add("// GENERATED by the MOH Coop Server GUI (hzm_server_gui.ps1) for profile '$($p.name)' - rewritten on every start.")
    $L.Add("// Holds this server's passwords: the GUI deletes it once the server has read it.")
    if (-not $Listen) { $L.Add("exec coop_mod/cfg/server_rules.cfg") }
    $L.Add("set sv_hostname `"$(Get-CleanValue $p.hostname)`"")
    $L.Add("set password `"$(Get-CleanValue $sec.password)`"")
    $L.Add("set rconPassword `"$(Get-CleanValue $sec.rcon)`"")
    $L.Add("set sv_gamespy $(if ($p.public) { 1 } else { 0 })")
    $L.Add("set sv_banFile `"hzm_servergui/$($p.name -replace '[^A-Za-z0-9_-]', '_')_bans.dat`"")
    foreach ($k in ($p.settings.Keys | Sort-Object)) {
        if (-not (Test-CvarName $k)) { continue }
        $e = $cat["_byName"][$k.ToLower()]
        if (-not $e) { continue }                                     # a cvar the catalogue no longer has is dropped
        if ($e["page"] -eq "server") { continue }                     # the Server tab owns those
        $L.Add("set $($e["name"]) `"$(Get-CleanValue $p.settings[$k])`"")
    }
    $campaign = if ($p.missionMode -eq "campaign") { 1 } else { 0 }
    $L.Add("set coop_campaign $campaign")
    if (-not $Listen) {
        $L.Add("set sv_autoRecord $(if ($p.recordMatches) { 1 } else { 0 })")
        # 0 = keep all: SVR_Rotate (sv_demo.c) skips a cap that is <= 0; a size cap is at least 50 MB
        $L.Add("set sv_autoRecordMax $([math]::Max(0, [int]$p.recordMaxFiles))")
        $rmb = [int]$p.recordMaxMB; $L.Add("set sv_autoRecordMaxMB $(if ($rmb -le 0) { 0 } else { [math]::Max(50, $rmb) })")
    }
    # bans and whitelist (ioq3 ban list: banaddr / exceptaddr, written to sv_banFile)
    $L.Add("flushbans")
    foreach ($b in @($p.bans)) { $ip = Get-CleanValue $b; if ($ip -match '^[0-9./]+$') { $L.Add("banaddr $ip") } }
    if ($p.whitelistOn -and @($p.whitelist).Count) {
        $L.Add("banaddr 0.0.0.0/0")
        foreach ($w in @($p.whitelist)) { $ip = Get-CleanValue $w; if ($ip -match '^[0-9./]+$') { $L.Add("exceptaddr $ip") } }
        $L.Add("exceptaddr 127.0.0.1")
    }
    $first = Get-FirstMap $p $cat
    if ($Listen) {
        # host-and-play: the coop start screen's own recipe (ui_startdmmap 2 via start_server.cfg / campaign_start.cfg).
        # `wait` lets the UI finish starting: ui_startdmmap is registered by CL_InitializeUI on the first frame.
        $L.Add("set ui_hostname `"$(Get-CleanValue $p.hostname)`"")
        $L.Add("set ui_maxclients $([int]$p.maxPlayers)")
        $L.Add("set sv_maxclients $([int]$p.maxPlayers)")
        $L.Add("set ui_gamespy $(if ($p.public) { 1 } else { 0 })")
        $L.Add("set ui_dedicated 0")
        if ($LightGraphics) { $L.Add("exec coop_mod/cfg/gfx_preset_low.cfg") }
        $L.Add("wait 120")
        if ($campaign) { $L.Add("exec coop_mod/cfg/campaign_start.cfg") }
        else {
            $fs = Split-MapSpec $first
            $L.Add("set ui_dmmap $($fs.Map)"); $L.Add("exec coop_mod/start_server.cfg")
            foreach ($k in $fs.Sets.Keys) { $L.Add("set $k $($fs.Sets[$k])") }    # after start_server.cfg, as the tile does
        }
    } else {
        $fs = Split-MapSpec $first
        foreach ($k in $fs.Sets.Keys) { $L.Add("set $k $($fs.Sets[$k])") }
        $L.Add("map $($fs.Map)")     # `map`, never ui_startdmmap (a client command - dedicated_example.cfg)
    }
    ($L -join "`r`n") + "`r`n"
}

function Get-ProfileTag($p) { $p.name -replace '[^A-Za-z0-9_-]', '_' }

function Get-DedicatedArgs($p, $inst) {
    $tag = Get-ProfileTag $p
    # g_gametype MUST be on the command line (latched); every value quoted; under Com_ParseCommandLine's 32-line cap
    @('+set', 'dedicated', '1', '+set', 'com_target_game', '2', '+set', 'g_gametype', '2',
      '+set', 'fs_basepath', "`"$($inst.Base)`"", '+set', 'fs_homepath', "`"$($inst.Home)`"",
      '+set', 'config', "hzm_server_$tag.cfg", '+set', 'logfile', '0',
      '+set', 'net_port', "$([int]$p.port)", '+set', 'net_gamespy_port', "$([int]$p.queryPort)",
      '+set', 'sv_maxclients', "$([int]$p.maxPlayers)", '+set', 'com_abnormalExit', '0',
      '+exec', "hzm_servergui/$tag.cfg")
}

function Get-ListenArgs($p, $inst, [switch]$LightGraphics) {
    $tag = Get-ProfileTag $p
    $a = $inst.LaunchArgs
    if (-not $a) { $a = "+set fs_basepath `"$($inst.Base)`" +set fs_homepath `"$($inst.Home)`" +set com_target_game 2" }
    if ($LightGraphics) { $a = ($a -replace '\+set cl_renderer \S+', '') + " +set cl_renderer opengl1" }
    elseif ($a -notmatch 'cl_renderer') { $a += " +set cl_renderer opengl2" }
    $a + " +set net_port $([int]$p.port) +set coop_reportLauncher servergui +exec hzm_servergui/${tag}_listen.cfg"
}

function Write-ServerCfg($p, $sec, $cat, $inst, [switch]$Listen, [switch]$LightGraphics) {
    $dir = Join-Path $inst.Maintt "hzm_servergui"
    if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
    $tag = Get-ProfileTag $p
    $f = if ($Listen) { Join-Path $dir "${tag}_listen.cfg" } else { Join-Path $dir "$tag.cfg" }
    [IO.File]::WriteAllText($f, (New-ServerCfgText $p $sec $cat -Listen:$Listen -LightGraphics:$LightGraphics), (New-Object Text.ASCIIEncoding))
    # the profile's own saved server config would carry a reset setting forward (archived cvars are written at exit,
    # TRAPS T7): start every boot from the shipped defaults + this cfg
    if (-not $Listen) { Remove-Item -LiteralPath (Join-Path $inst.Maintt "configs\hzm_server_$tag.cfg") -Force -ErrorAction SilentlyContinue }
    $f
}

# ======================================================================================================================
# missions: the generated boards + the own-disc (BYO) missions converted on THIS PC
# ======================================================================================================================
function Get-ByoMaps($inst) {
    # a BYO mission exists here when a zzzz_coop_*.pk3 that byo_convert.ps1 wrote holds maps/<map>.bsp
    $found = @{}
    Add-Type -AssemblyName System.IO.Compression.FileSystem
    foreach ($dir in @($inst.Maintt, (Join-Path $inst.Base "maintt")) | Select-Object -Unique) {
        foreach ($pk in @(Get-ChildItem -LiteralPath $dir -Filter "zzzz_coop_*.pk3" -File -ErrorAction SilentlyContinue)) {
            try {
                $z = [IO.Compression.ZipFile]::OpenRead($pk.FullName)
                try { foreach ($en in $z.Entries) { if ($en.FullName -match '^maps/(coop_[A-Za-z0-9_]+)\.bsp$') { $found[$Matches[1]] = $pk.Name } } }
                finally { $z.Dispose() }
            } catch {}
        }
    }
    $found
}

# ======================================================================================================================
# PC specs
# ======================================================================================================================
if (-not ("HzmCpu" -as [type])) {
Add-Type -TypeDefinition @"
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
public class HzmCore { public int Index; public int Efficiency; public bool Smt; public List<int> Threads = new List<int>(); }
public static class HzmCpu {
    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool GetLogicalProcessorInformationEx(int rel, IntPtr buf, ref uint len);
    [StructLayout(LayoutKind.Sequential)]
    struct PPTS { public uint Version; public uint ControlMask; public uint StateMask; }
    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool SetProcessInformation(IntPtr h, int cls, ref PPTS s, uint size);
    // the server must never be power-throttled in the background (public_servers/run_server.ps1, same call)
    public static bool NoThrottle(IntPtr h) {
        var s = new PPTS { Version = 1, ControlMask = 1 | 4, StateMask = 0 };
        return SetProcessInformation(h, 4, ref s, (uint)Marshal.SizeOf(s));
    }
    public static List<HzmCore> Cores() {
        var list = new List<HzmCore>();
        uint len = 0;
        GetLogicalProcessorInformationEx(0, IntPtr.Zero, ref len);   // RelationProcessorCore
        IntPtr buf = Marshal.AllocHGlobal((int)len);
        try {
            if (!GetLogicalProcessorInformationEx(0, buf, ref len)) return list;
            int off = 0, idx = 0;
            while (off < len) {
                IntPtr p = new IntPtr(buf.ToInt64() + off);
                int size = Marshal.ReadInt32(p, 4);
                byte flags = Marshal.ReadByte(p, 8);
                byte eff = Marshal.ReadByte(p, 9);
                int groups = Marshal.ReadInt16(p, 30);
                var c = new HzmCore { Index = idx++, Efficiency = eff, Smt = (flags & 1) != 0 };
                for (int g = 0; g < groups; g++) {
                    long mask = Marshal.ReadInt64(p, 32 + g * 16);
                    int grp = Marshal.ReadInt16(p, 32 + g * 16 + 8);
                    for (int b = 0; b < 64; b++) if (((mask >> b) & 1) != 0) c.Threads.Add(grp * 64 + b);
                }
                list.Add(c);
                off += size;
            }
        } finally { Marshal.FreeHGlobal(buf); }
        return list;
    }
}
"@
}

function Get-ThreadLoad {
    # per-logical-processor busy %, from two WMI samples (formatted counters, locale-independent)
    $load = @{}
    try {
        $null = Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -ErrorAction Stop
        Start-Sleep -Milliseconds 700
        foreach ($r in Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -ErrorAction Stop) {
            if ($r.Name -match '^\d+$') { $load[[int]$r.Name] = [int]$r.PercentProcessorTime }
        }
    } catch {}
    $load
}

function Get-GpuInfo {
    $out = @()
    $regMem = @{}
    try {
        $cls = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
        foreach ($k in Get-ChildItem -LiteralPath $cls -ErrorAction SilentlyContinue) {
            $pr = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
            if ($pr.DriverDesc) {
                $mem = $pr.'HardwareInformation.qwMemorySize'
                if (-not $mem) { $mem = $pr.'HardwareInformation.MemorySize' }
                if ($mem -is [byte[]]) { $mem = [BitConverter]::ToUInt64(($mem + (New-Object byte[] 8))[0..7], 0) }
                if ($mem) { $regMem[$pr.DriverDesc] = [double]$mem }
            }
        }
    } catch {}
    foreach ($v in Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue) {
        $n = "$($v.Name)"
        if ($n -match 'Basic Display|Remote Display|Virtual|Parsec|Meta|Mirage|DisplayLink') { continue }
        $vram = if ($regMem.ContainsKey($n)) { $regMem[$n] } else { [double]$v.AdapterRAM }
        $integrated = $false
        if ($n -match 'Intel' -and $n -notmatch '\bArc\b') { $integrated = $true }
        if ($n -match 'AMD|Radeon' -and $n -notmatch '\bRX\b|\bPro\b|FirePro|Vega 56|Vega 64|Radeon VII' -and
            ($n -match 'Radeon\(TM\) Graphics|Radeon Graphics|Vega \d\b|\b(610|660|680|740|760|780|880|890)M\b')) { $integrated = $true }
        if ($vram -gt 0 -and $vram -lt 900MB -and $n -notmatch 'NVIDIA|GeForce|Quadro|RTX|GTX') { $integrated = $true }
        $out += [pscustomobject]@{ Name = $n; VramMB = [int]($vram / 1MB); Integrated = $integrated; Driver = "$($v.DriverVersion)" }
    }
    $out
}

function Get-PcSpecs([switch]$NoLoad) {
    $cpu = Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue | Select-Object -First 1
    $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue
    $os = Get-CimInstance Win32_OperatingSystem -ErrorAction SilentlyContinue
    $cores = @()
    try { $cores = @([HzmCpu]::Cores()) } catch {}
    $maxEff = 0; foreach ($c in $cores) { if ($c.Efficiency -gt $maxEff) { $maxEff = $c.Efficiency } }
    $hybrid = @($cores | Select-Object -ExpandProperty Efficiency -Unique).Count -gt 1
    $load = if ($NoLoad) { @{} } else { Get-ThreadLoad }
    $inst = Get-Install
    $drive = $null
    try { $drive = Get-PSDrive -Name ((Resolve-Path -LiteralPath $inst.Root).Path.Substring(0, 1)) -ErrorAction Stop } catch {}
    [pscustomobject]@{
        CpuName = "$($cpu.Name)".Trim(); Cores = $cores.Count; Threads = [int]$cs.NumberOfLogicalProcessors
        Hybrid = $hybrid; PCores = @($cores | Where-Object { $_.Efficiency -eq $maxEff }).Count
        ECores = @($cores | Where-Object { $_.Efficiency -ne $maxEff }).Count; MaxEff = $maxEff
        CoreList = $cores; Load = $load; MaxMHz = [int]$cpu.MaxClockSpeed
        RamGB = [math]::Round([double]$cs.TotalPhysicalMemory / 1GB, 1)
        FreeRamGB = [math]::Round([double]$os.FreePhysicalMemory * 1KB / 1GB, 1)
        Gpus = @(Get-GpuInfo)
        DiskFreeGB = if ($drive) { [math]::Round($drive.Free / 1GB, 1) } else { 0 }
        DiskName = if ($drive) { "$($drive.Name):" } else { "?" }
    }
}

function Get-RecommendedThread($specs, [int[]]$busyThreads = @()) {
    # a P-core (highest efficiency class), the least-loaded one, never core 0 (interrupts and the desktop land there)
    # when there is a choice, and never a core whose SMT sibling is busy: the server is single-threaded and shares
    # its core's execution units with the sibling
    $cands = @($specs.CoreList | Where-Object { $_.Efficiency -eq $specs.MaxEff })
    if ($cands.Count -gt 1) { $cands = @($cands | Where-Object { $_.Index -ne 0 }) }
    $best = $null; $bestScore = [double]::MaxValue
    foreach ($c in $cands) {
        $score = 0.0
        foreach ($t in $c.Threads) {
            $l = if ($specs.Load.ContainsKey($t)) { [double]$specs.Load[$t] } else { 0.0 }
            if ($busyThreads -contains $t) { $l += 100 }
            $score += $l
        }
        if ($score -lt $bestScore) { $bestScore = $score; $best = $c }
    }
    if (-not $best) { return $null }
    [pscustomobject]@{ Thread = $best.Threads[0]; Core = $best.Index; Siblings = @($best.Threads | Select-Object -Skip 1); Load = $bestScore }
}

function Get-SuggestedPlayers($specs, [double]$uploadMbps = 0, [switch]$HostAndPlay) {
    # ~0.45 Mbit/s up per player in a heavy firefight at sv_fps 40 / rate 60000 (server_topology_and_limits.md)
    $why = @()
    $n = 8
    if ($uploadMbps -gt 0) { $u = [int][math]::Floor($uploadMbps / 0.5); $why += "upload $uploadMbps Mbit/s allows about $u"; $n = [math]::Min($n, $u) }
    else { $n = [math]::Min($n, 4); $why += "upload not tested yet: 4 until it is" }
    if ($specs.Threads -le 2) { $n = [math]::Min($n, 4); $why += "2 threads" }
    if ($specs.RamGB -lt 8) { $n = [math]::Min($n, 4); $why += "$($specs.RamGB) GB RAM" }
    if ($HostAndPlay -and @($specs.Gpus | Where-Object { -not $_.Integrated }).Count -eq 0) { $n = [math]::Min($n, 4); $why += "host-and-play on an integrated GPU" }
    $n = [math]::Max(1, $n)
    [pscustomobject]@{ Players = $n; Why = ($why -join "; ") }
}

function Test-UploadSpeed([string]$url = $SpeedTestUrl, [int]$bytes = 4MB) {
    # opt-in only (a button): POST random bytes and time the upload
    $data = New-Object byte[] $bytes
    (New-Object Random).NextBytes($data)
    $req = [Net.HttpWebRequest]::Create($url)
    $req.Method = "POST"; $req.ContentType = "application/octet-stream"; $req.ContentLength = $data.Length
    $req.Timeout = 60000; $req.UserAgent = "MOHCoopServerGUI/$($script:Version)"
    $sw = [Diagnostics.Stopwatch]::StartNew()
    $s = $req.GetRequestStream(); $s.Write($data, 0, $data.Length); $s.Close()
    $resp = $req.GetResponse(); $resp.Close()
    $sw.Stop()
    [math]::Round(($bytes * 8 / 1e6) / [math]::Max($sw.Elapsed.TotalSeconds, 0.001), 1)
}

# ======================================================================================================================
# talking to a server: getstatus and rcon (0xFF x4 + the 0x02 direction byte - docs/tools/rcon.py, bug-1143)
# ======================================================================================================================
function Send-Oob([string]$text, [int]$port, [string]$hostName = "127.0.0.1", [int]$timeoutMs = 1500) {
    $u = New-Object Net.Sockets.UdpClient
    try {
        $u.Client.ReceiveTimeout = $timeoutMs
        $pkt = [byte[]](255, 255, 255, 255, 2) + [Text.Encoding]::GetEncoding(28591).GetBytes($text)
        [void]$u.Send($pkt, $pkt.Length, $hostName, $port)
        $sb = New-Object Text.StringBuilder
        $ep = New-Object Net.IPEndPoint([Net.IPAddress]::Any, 0)
        while ($true) {
            try { $d = $u.Receive([ref]$ep) } catch { break }
            $i = 0; while ($i -lt $d.Length -and $d[$i] -eq 255) { $i++ }
            if ($i -lt $d.Length -and ($d[$i] -eq 1 -or $d[$i] -eq 2)) { $i++ }
            $t = [Text.Encoding]::GetEncoding(28591).GetString($d, $i, $d.Length - $i)
            if ($t.StartsWith("print")) { $t = $t.Substring(5).TrimStart("`n") }
            [void]$sb.Append($t)
            $u.Client.ReceiveTimeout = 300
        }
        $sb.ToString()
    } finally { $u.Close() }
}
function Invoke-Rcon([int]$port, [string]$pw, [string]$cmd) {
    if (-not $pw) { return "(no rcon password)" }
    $cmd = $cmd -replace '[\r\n]', ' '
    Send-Oob "rcon $pw $cmd" $port
}
function Get-ServerStatus([int]$port) {
    $t = Send-Oob "getstatus" $port
    if (-not $t) { return $null }
    $lines = $t -split "`n"
    $kv = @{}
    if ($lines.Count -gt 1) {
        $f = $lines[1].Split('\'); for ($i = 1; $i + 1 -lt $f.Count; $i += 2) { $kv[$f[$i]] = $f[$i + 1] }
    }
    $pl = @()
    foreach ($l in ($lines | Select-Object -Skip 2)) {
        if ($l -match '^\s*(-?\d+)\s+(\d+)\s+"(.*)"\s*$') { $pl += [pscustomobject]@{ Num = ""; Name = $Matches[3]; Score = $Matches[1]; Ping = $Matches[2]; Address = "" } }
    }
    [pscustomobject]@{ Info = $kv; Players = $pl }
}
function Get-RconPlayers([int]$port, [string]$pw) {
    # rcon status: num score ping name lastmsg address qport rate
    $t = Invoke-Rcon $port $pw "status"
    $out = @()
    foreach ($l in ($t -split "`n")) {
        if ($l -match '^\s*(\d+)\s+(-?\d+)\s+(\S+)\s+(.+?)\s+(\d+)\s+(\S+)\s+(\d+)\s+(\d+)\s*$') {
            $out += [pscustomobject]@{ Num = $Matches[1]; Score = $Matches[2]; Ping = $Matches[3]; Name = $Matches[4].Trim(); Address = $Matches[6] }
        }
    }
    , $out
}
function Remove-ColorCodes([string]$s) { [regex]::Replace("$s", '\^[0-9A-Za-z]', '') }

# ======================================================================================================================
# Discord webhook (server up/down, player joined/left)
# ======================================================================================================================
function Test-WebhookUrl([string]$u) {
    ($u -match '^https://(discord|discordapp|ptb\.discord|canary\.discord)\.com/api/webhooks/\d+/[A-Za-z0-9_-]+$') -or
    ($u -match '^http://(127\.0\.0\.1|localhost)(:\d+)?/')      # a local listener, for testing only
}
function Send-Webhook([string]$url, [string]$text) {
    if (-not $url -or -not (Test-WebhookUrl $url)) { return $false }
    $body = @{ username = "MOH Coop Server"; content = $text.Substring(0, [math]::Min(1900, $text.Length)); allowed_mentions = @{ parse = @() } } | ConvertTo-Json -Compress
    try {
        Invoke-RestMethod -Uri $url -Method Post -ContentType "application/json; charset=utf-8" -Body ([Text.Encoding]::UTF8.GetBytes($body)) -TimeoutSec 10 | Out-Null
        Write-Log "webhook sent: $text"
        $true
    } catch { Write-Log "webhook failed: $($_.Exception.Message)"; $false }
}

# ======================================================================================================================
# network helpers: local/public IP, UPnP, firewall (each asked first in the GUI; -DryRun never executes)
# ======================================================================================================================
function Get-LocalIp {
    try {
        $r = Get-NetRoute -DestinationPrefix "0.0.0.0/0" -ErrorAction Stop | Sort-Object RouteMetric | Select-Object -First 1
        (Get-NetIPAddress -InterfaceIndex $r.ifIndex -AddressFamily IPv4 -ErrorAction Stop | Select-Object -First 1).IPAddress
    } catch { "" }
}
function Get-PublicIp { try { (Invoke-RestMethod -Uri $PublicIpUrl -TimeoutSec 8).ToString().Trim() } catch { "" } }

function Invoke-UpnpForward($p, [switch]$Remove) {
    $ip = Get-LocalIp
    $ports = @([int]$p.port, [int]$p.queryPort)
    $desc = "MOH Coop Server $($p.name)"
    if ($DryRun) {
        foreach ($pt in $ports) { Write-DryRun ("UPnP {0} UDP {1} -> {2}:{1} ({3})" -f $(if ($Remove) { "remove" } else { "add" }), $pt, $ip, $desc) }
        return "dry run: UPnP $(if ($Remove) { 'removal' } else { 'mapping' }) of UDP $($ports -join ', ') to $ip logged, nothing sent to the router"
    }
    $nat = New-Object -ComObject HNetCfg.NATUPnP
    $col = $nat.StaticPortMappingCollection
    if (-not $col) { return "no UPnP router answered (UPnP off on the router, or Network Discovery off on this PC)" }
    foreach ($pt in $ports) {
        if ($Remove) { try { $col.Remove($pt, "UDP") } catch {} }
        else { [void]$col.Add($pt, "UDP", $pt, $ip, $true, $desc) }
    }
    Write-Log "UPnP $(if ($Remove) { 'removed' } else { 'added' }) UDP $($ports -join ',') -> $ip"
    "done: UDP $($ports -join ', ') $(if ($Remove) { 'removed from' } else { 'forwarded to ' + $ip + ' on' }) the router"
}

function Get-FirewallCommand($p, $inst) {
    $n = "MOH Coop Server - $($p.name)" -replace "'", ""
    "New-NetFirewallRule -DisplayName '$n' -Direction Inbound -Action Allow -Protocol UDP -LocalPort $([int]$p.port),$([int]$p.queryPort) -Program '$($inst.Ded -replace "'", "''")' -Profile Any"
}
function Test-FirewallRule($p) {
    try { [bool](Get-NetFirewallRule -DisplayName "MOH Coop Server - $($p.name)" -ErrorAction Stop) } catch { $false }
}
function Invoke-FirewallRule($p, $inst) {
    $cmd = Get-FirewallCommand $p $inst
    if ($DryRun) { Write-DryRun "elevated: $cmd"; return "dry run: the firewall command was logged, not run" }
    # elevate ONLY for this one command
    $enc = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($cmd))
    try {
        $pr = Start-Process -FilePath "powershell.exe" -Verb RunAs -WindowStyle Hidden -PassThru -Wait -ArgumentList "-NoProfile -EncodedCommand $enc"
        Write-Log "firewall rule command exit $($pr.ExitCode)"
        if (Test-FirewallRule $p) { "done: inbound UDP $($p.port), $($p.queryPort) allowed for omohaaded.exe" } else { "the rule was not added (exit $($pr.ExitCode))" }
    } catch { "cancelled - nothing was changed" }
}

function Set-StartWithWindows($p, [bool]$on) {
    $key = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run'
    $val = "MOHCoopServer_$(Get-ProfileTag $p)"
    $vbs = Join-Path $script:GuiDir "hzm_server_gui.vbs"
    $how = if ("$($p.startupMode)" -eq "window") { "-StartProfile" } else { "-Supervise" }
    $cmd = "wscript.exe `"$vbs`" $how `"$($p.name)`""
    if ($DryRun) { Write-DryRun "HKCU Run $val = $(if ($on) { $cmd } else { '(removed)' })"; return }
    if ($on) { New-ItemProperty -Path $key -Name $val -Value $cmd -PropertyType String -Force | Out-Null }
    else { Remove-ItemProperty -Path $key -Name $val -ErrorAction SilentlyContinue }
}

# ======================================================================================================================
# supervisor: state files, start/stop, the loop
# ======================================================================================================================
function Get-RunPath($p, [string]$ext) { Join-Path $DataDir ("run\{0}.{1}" -f (Get-ProfileTag $p), $ext) }
function Get-State($p) {
    $f = Get-RunPath $p "state.json"
    if (Test-Path -LiteralPath $f) { try { return Get-Content -LiteralPath $f -Raw | ConvertFrom-Json } catch {} }
    $null
}
function Test-Running($p) {
    $s = Get-State $p
    if (-not $s -or -not $s.supervisorPid) { return $false }
    $pr = Get-Process -Id $s.supervisorPid -ErrorAction SilentlyContinue
    [bool]($pr -and $pr.ProcessName -match 'powershell')
}
function Start-Supervisor($p) {
    Remove-Item -LiteralPath (Get-RunPath $p "stop") -Force -ErrorAction SilentlyContinue
    $self = $script:GuiPath
    $cmd = "powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$self`" -Supervise `"$($p.name)`" -DataDir `"$DataDir`" -InstallRoot `"$InstallRoot`""
    if ($Catalogue) { $cmd += " -Catalogue `"$Catalogue`"" }
    if ($DryRun) { $cmd += " -DryRun" }
    # WMI: the supervisor's parent is WmiPrvSE, so it outlives this window and any shell (bug-11282); window hidden
    $si = New-CimInstance -ClassName Win32_ProcessStartup -ClientOnly -Property @{ ShowWindow = [uint16]0 }
    $r = Invoke-CimMethod -ClassName Win32_Process -MethodName Create -Arguments @{ CommandLine = $cmd; CurrentDirectory = $script:GuiDir; ProcessStartupInformation = $si }
    Write-Log "supervisor for '$($p.name)' started (pid $($r.ProcessId), rc $($r.ReturnValue))"
    $r.ProcessId
}
function Stop-Supervisor($p) { Set-Content -LiteralPath (Get-RunPath $p "stop") -Value "stop" -Encoding ascii }
function Send-SupervisorCommand($p, [string]$c) { Add-Content -LiteralPath (Get-RunPath $p "cmd") -Value $c -Encoding ascii }

function Remove-OldLogs($p) {
    $dir = Join-Path $DataDir ("logs\" + (Get-ProfileTag $p))
    $keep = [math]::Max(1, [int]$p.logKeepDays)
    Get-ChildItem -LiteralPath $dir -File -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -lt (Get-Date).AddDays(-$keep) } |
        ForEach-Object { Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue }
}

function Sync-MatchDemos($p, $inst) {
    # a demo is FINISHED once the recorder wrote its .dmi info file (SVR_Close); copy every finished auto_ demo and its
    # side files to the chosen folder, then keep that folder under its size and age caps (oldest first). The engine's
    # own demos\ copy and its rotation are left alone (the Film Room downloads "@last" from there).
    if (-not $p.recordFolder) { return }
    $src = Join-Path $inst.Maintt "demos"
    if (-not (Test-Path -LiteralPath $src)) { return }
    if (-not (Test-Path -LiteralPath $p.recordFolder)) { New-Item -ItemType Directory -Force -Path $p.recordFolder | Out-Null }
    # a ledger of what was copied once: a demo the caps removed from the folder is never copied back
    $ledger = Join-Path $p.recordFolder "copied_demos.txt"
    $done = @{}
    if (Test-Path -LiteralPath $ledger) { foreach ($l in Get-Content -LiteralPath $ledger) { $done[$l] = 1 } }
    # 0 days = no age limit (0 GB = no size limit, below)
    $maxDays = [int]$p.recordFolderMaxDays
    $oldestCopy = if ($maxDays -gt 0) { (Get-Date).AddDays(-$maxDays) } else { [datetime]::MinValue }
    foreach ($dmi in @(Get-ChildItem -LiteralPath $src -Filter "auto_*.dmi" -File -ErrorAction SilentlyContinue)) {
        $base = [IO.Path]::GetFileNameWithoutExtension($dmi.Name)
        if ($done.ContainsKey($base) -or $dmi.LastWriteTime -lt $oldestCopy) { continue }
        foreach ($f in @(Get-ChildItem -LiteralPath $src -Filter "$base.*" -File -ErrorAction SilentlyContinue)) {
            $dst = Join-Path $p.recordFolder $f.Name
            if (-not (Test-Path -LiteralPath $dst)) { Copy-Item -LiteralPath $f.FullName -Destination $dst -ErrorAction SilentlyContinue }
        }
        Add-Content -LiteralPath $ledger -Value $base -Encoding ascii
    }
    $all = @(Get-ChildItem -LiteralPath $p.recordFolder -Filter "auto_*.*" -File -ErrorAction SilentlyContinue)
    $groups = @($all | Group-Object { [IO.Path]::GetFileNameWithoutExtension($_.Name) } |
        Sort-Object { ($_.Group | Measure-Object LastWriteTime -Maximum).Maximum })
    $total = ($all | Measure-Object Length -Sum).Sum
    $capBytes = [double]$p.recordFolderMaxGB * 1GB
    $oldest = $oldestCopy
    foreach ($g in $groups) {
        $age = ($g.Group | Measure-Object LastWriteTime -Maximum).Maximum
        if (($capBytes -gt 0 -and $total -gt $capBytes) -or $age -lt $oldest) {
            foreach ($f in $g.Group) { $total -= $f.Length; Remove-Item -LiteralPath $f.FullName -Force -ErrorAction SilentlyContinue }
        }
    }
}

function Invoke-Supervisor([string]$name) {
    $p = Read-Profile $name
    $tag = Get-ProfileTag $p
    $mutex = New-Object Threading.Mutex($false, "Local\MOHCoopServer_$tag")
    if (-not $mutex.WaitOne(0)) { Write-Log "supervisor '$name' already running - exit"; return }
    $logDir = Join-Path $DataDir "logs\$tag"
    if (-not (Test-Path -LiteralPath $logDir)) { New-Item -ItemType Directory -Force -Path $logDir | Out-Null }
    $slog = Join-Path $logDir "supervisor.log"
    function SLog($m) { Write-Log $m $slog }
    $cat = Import-Catalogue
    $inst = Get-Install
    $state = [ordered]@{ profile = $name; supervisorPid = $PID; serverPid = 0; state = "starting"; started = ""; restarts = 0; log = ""; map = ""; port = $p.port; players = 0; playerList = @() }
    function Save-State { $state | ConvertTo-Json | Set-Content -LiteralPath (Get-RunPath $p "state.json") -Encoding UTF8 }
    Save-State
    $stopFile = Get-RunPath $p "stop"; $cmdFile = Get-RunPath $p "cmd"
    Remove-Item -LiteralPath $cmdFile -Force -ErrorAction SilentlyContinue
    $lastDaily = ""
    $userStop = $false
    try {
        while ($true) {
            if (Test-Path -LiteralPath $stopFile) { $userStop = $true; break }
            $p = Read-Profile $name          # pick up changes saved in the GUI since the last start
            $sec = Read-Secrets $name
            if (-not $sec.rcon) { $sec.rcon = New-RandomPassword; Save-Secrets $name $sec }
            Remove-OldLogs $p
            if ($p.updateOnStart -and (Test-Path -LiteralPath $inst.Updater)) {
                $others = @(Get-CimInstance Win32_Process -Filter "Name='omohaaded.exe'" -ErrorAction SilentlyContinue | Where-Object { $_.ExecutablePath -eq $inst.Ded })
                if ($others.Count -eq 0) {
                    SLog "checking for updates (updater.ps1 -NoLaunch)"
                    $state.state = "updating"; Save-State
                    $u = Start-Process -FilePath "powershell.exe" -WindowStyle Hidden -PassThru -Wait -ArgumentList @("-NoProfile", "-ExecutionPolicy", "Bypass", "-File", "`"$($inst.Updater)`"", "-NoLaunch")
                    SLog "updater exit $($u.ExitCode)"
                } else { SLog "update check skipped: another server of this install is running" }
            }
            $cfg = Write-ServerCfg $p $sec $cat $inst
            $log = Join-Path $logDir ("server_{0:yyyyMMdd_HHmmss}.log" -f (Get-Date))
            $pr = Start-Process -FilePath $inst.Ded -WorkingDirectory $inst.Root -ArgumentList (Get-DedicatedArgs $p $inst) -PassThru -NoNewWindow `
                -RedirectStandardError $log -RedirectStandardOutput "$log.out"
            Start-Sleep -Milliseconds 800
            try { $pr.PriorityClass = $p.priority } catch { SLog "priority: $_" }
            try { [void][HzmCpu]::NoThrottle($pr.Handle) } catch {}
            if (@($p.affinity).Count) {
                $mask = [int64]0; foreach ($t in $p.affinity) { if ($t -lt 63) { $mask = $mask -bor ([int64]1 -shl $t) } }
                try { $pr.ProcessorAffinity = [IntPtr]$mask } catch { SLog "affinity: $_" }
            }
            $state.serverPid = $pr.Id; $state.state = "booting"; $state.started = (Get-Date).ToString("s"); $state.log = $log; Save-State
            SLog "server pid $($pr.Id) port $($p.port) log $log"
            $pos = 0; $booted = $false; $known = @{}; $nextPoll = (Get-Date).AddSeconds(15); $nextMotd = $null
            $rotIdx = 0; $rot = @($p.rotation | Where-Object { Test-MapSpec $_ }); $rotPending = $false; $rotCmd = $null
            $loaded = $false; $seenMap = ""; $nextStatus = Get-Date; $nextDemoSync = (Get-Date).AddSeconds(30)
            if ($p.motdRepeatMin -gt 0) { $nextMotd = (Get-Date).AddMinutes([int]$p.motdRepeatMin) }
            while (-not $pr.HasExited) {
                Start-Sleep -Milliseconds 1000
                # --- the console log: "Server: <map>" starts a map LOAD. The server answers no packet until the load is
                # done. A load started by an rcon command prints into the rcon REPLY, not the console (the engine redirects
                # output while rcon runs), so the map itself is read from getstatus below, never from this line alone.
                try {
                    $fs = [IO.File]::Open($log, 'Open', 'Read', 'ReadWrite')
                    try {
                        if ($fs.Length -gt $pos) {
                            [void]$fs.Seek($pos, 'Begin'); $buf = New-Object byte[] ($fs.Length - $pos); $n = $fs.Read($buf, 0, $buf.Length); $pos += $n
                            foreach ($ln in ([Text.Encoding]::GetEncoding(28591).GetString($buf, 0, $n) -split "`n")) {
                                if ($ln -match '^Server: (\S+)') {
                                    $state.map = $Matches[1]; $state.state = "loading"; $loaded = $false; Save-State
                                    Remove-Item -LiteralPath $cfg -Force -ErrorAction SilentlyContinue   # it held the passwords
                                }
                            }
                        }
                    } finally { $fs.Close() }
                } catch {}
                # --- getstatus: up, and which map (1 s while loading, else every 3 s) ---
                if ((Get-Date) -ge $nextStatus) {
                    $gs = Get-ServerStatus $p.port
                    $nextStatus = (Get-Date).AddSeconds($(if ($loaded) { 3 } else { 1 }))
                    if ($gs -and $gs.Info["mapname"]) {
                        $m = $gs.Info["mapname"]
                        if (-not $loaded) { $loaded = $true; $state.state = "running" }
                        if (-not $booted) {
                            $booted = $true
                            Remove-Item -LiteralPath $cfg -Force -ErrorAction SilentlyContinue
                            SLog "booted on $m"
                            if ($p.hookUp) { [void](Send-Webhook $sec.webhook ("Server up: **{0}** - {1} (port {2})" -f (Remove-ColorCodes $p.hostname), $m, $p.port)) }
                        }
                        if ($m -ne $seenMap) {
                            $seenMap = $m; $state.map = $m
                            SLog "map: $m"
                            if ($p.missionMode -eq "rotation" -and $rot.Count) {
                                # only the current entry (a restart of it) or the next one may run; anything else is the
                                # story's own next mission (missioncomplete), replaced by the next rotation entry
                                $cur = Split-MapSpec $rot[$rotIdx]; $nextIdx = ($rotIdx + 1) % $rot.Count; $nxt = Split-MapSpec $rot[$nextIdx]
                                if ($m -eq $cur.Map) { $rotPending = $false }
                                elseif (-not $rotPending -and $m -eq $nxt.Map -and $nxt.Sets.Count -eq 0) { $rotIdx = $nextIdx }
                                else {
                                    if (-not $rotPending) { $rotIdx = $nextIdx }
                                    $rotPending = $true; $rotCmd = Split-MapSpec $rot[$rotIdx]
                                    SLog "rotation: $m is not next in the rotation - loading $($rot[$rotIdx])"
                                }
                            }
                        }
                        Save-State
                        if ($rotCmd) {
                            foreach ($k in $rotCmd.Sets.Keys) { [void](Invoke-Rcon $p.port $sec.rcon "set $k $($rotCmd.Sets[$k])") }
                            [void](Invoke-Rcon $p.port $sec.rcon "map $($rotCmd.Map)")
                            $rotCmd = $null; $loaded = $false; $nextStatus = (Get-Date).AddSeconds(2)
                        }
                    }
                }
                if (Test-Path -LiteralPath $stopFile) {
                    $userStop = $true
                    [void](Invoke-Rcon $p.port $sec.rcon "quit")
                    if (-not $pr.WaitForExit(6000)) { Stop-Process -Id $pr.Id -Force -ErrorAction SilentlyContinue }
                    break
                }
                if (Test-Path -LiteralPath $cmdFile) {
                    $cmds = @(Get-Content -LiteralPath $cmdFile); Remove-Item -LiteralPath $cmdFile -Force -ErrorAction SilentlyContinue
                    if ($cmds -contains "restart") {
                        SLog "restart requested"
                        [void](Invoke-Rcon $p.port $sec.rcon "quit")
                        if (-not $pr.WaitForExit(6000)) { Stop-Process -Id $pr.Id -Force -ErrorAction SilentlyContinue }
                        $state.restarts++; break
                    }
                }
                if ($p.recordFolder -and (Get-Date) -ge $nextDemoSync) {
                    $nextDemoSync = (Get-Date).AddSeconds(30)
                    try { Sync-MatchDemos $p $inst } catch { SLog "demo copy: $_" }
                }
                # --- scheduled daily restart ---
                if ($p.dailyRestart -match '^(\d{1,2}):(\d{2})$') {
                    $now = Get-Date; $today = $now.ToString("yyyy-MM-dd")
                    if ($lastDaily -ne $today -and $now.Hour -eq [int]$Matches[1] -and $now.Minute -eq [int]$Matches[2]) {
                        $lastDaily = $today
                        SLog "scheduled daily restart"
                        [void](Invoke-Rcon $p.port $sec.rcon "say Scheduled restart in 60 seconds")
                        Start-Sleep -Seconds 60
                        [void](Invoke-Rcon $p.port $sec.rcon "quit")
                        if (-not $pr.WaitForExit(6000)) { Stop-Process -Id $pr.Id -Force -ErrorAction SilentlyContinue }
                        $state.restarts++; break
                    }
                }
                # --- players: joined / left (rcon status every 10 s) + MOTD ---
                if ($booted -and (Get-Date) -ge $nextPoll) {
                    $nextPoll = (Get-Date).AddSeconds(10)
                    $now = @{}
                    foreach ($pl in (Get-RconPlayers $p.port $sec.rcon)) { $now["$($pl.Num)|$($pl.Name)"] = $pl }
                    foreach ($k in $now.Keys) {
                        if (-not $known.ContainsKey($k)) {
                            $pn = Remove-ColorCodes $now[$k].Name
                            SLog "joined: $pn"
                            if ($p.hookJoin) { [void](Send-Webhook $sec.webhook ("**{0}** joined {1} ({2} online)" -f $pn, (Remove-ColorCodes $p.hostname), $now.Count)) }
                            if ($p.motd) { [void](Invoke-Rcon $p.port $sec.rcon ("tell {0} {1}" -f $now[$k].Num, (Get-CleanValue $p.motd))) }
                        }
                    }
                    foreach ($k in @($known.Keys)) {
                        if (-not $now.ContainsKey($k)) {
                            $pn = Remove-ColorCodes $known[$k].Name
                            SLog "left: $pn"
                            if ($p.hookLeave) { [void](Send-Webhook $sec.webhook ("**{0}** left {1} ({2} online)" -f $pn, (Remove-ColorCodes $p.hostname), $now.Count)) }
                        }
                    }
                    $known = $now; $state.players = $now.Count
                    $state.playerList = @($now.Values | Sort-Object { [int]$_.Num } | Select-Object Num, Name, Score, Ping, Address); Save-State
                }
                if ($booted -and $nextMotd -and $p.motd -and (Get-Date) -ge $nextMotd) {
                    $nextMotd = (Get-Date).AddMinutes([int]$p.motdRepeatMin)
                    if ($known.Count) { [void](Invoke-Rcon $p.port $sec.rcon ("say {0}" -f (Get-CleanValue $p.motd))) }
                }
            }
            Remove-Item -LiteralPath $cfg -Force -ErrorAction SilentlyContinue
            try { Sync-MatchDemos $p $inst } catch {}      # the map's demo was closed on exit
            $code = -1; try { $code = $pr.ExitCode } catch {}
            SLog "server exited (code $code)"
            if ($userStop) { break }
            $crashed = ($code -ne 0)
            if ($p.hookDown) { [void](Send-Webhook $sec.webhook ("Server {0}: **{1}** (exit code {2})" -f $(if ($crashed) { "crashed" } else { "stopped" }), (Remove-ColorCodes $p.hostname), $code)) }
            if (-not $p.autoRestart) { break }
            $state.state = "restarting"; $state.restarts++; Save-State
            for ($i = 0; $i -lt 10; $i++) { if (Test-Path -LiteralPath $stopFile) { break }; Start-Sleep -Seconds 1 }
        }
    } finally {
        if ($userStop -and $p.hookDown) { [void](Send-Webhook $sec.webhook ("Server stopped: **{0}**" -f (Remove-ColorCodes $p.hostname))) }
        $state.state = "stopped"; $state.serverPid = 0; $state.players = 0; $state.playerList = @(); Save-State
        Remove-Item -LiteralPath $stopFile -Force -ErrorAction SilentlyContinue
        SLog "supervisor exit"
        $mutex.ReleaseMutex()
    }
}

function Start-ListenServer($p, $sec, $cat, $inst, [bool]$light) {
    if (Get-Process openmohaa -ErrorAction SilentlyContinue) { return "the game is already running - close it first" }
    if (-not $sec.rcon) { $sec.rcon = New-RandomPassword; Save-Secrets $p.name $sec }
    $cfgFile = Write-ServerCfg $p $sec $cat $inst -Listen -LightGraphics:$light
    $a = Get-ListenArgs $p $inst -LightGraphics:$light
    Start-Process -FilePath $inst.Client -ArgumentList $a -WorkingDirectory $inst.Root | Out-Null
    # the cfg holds the passwords: gone 3 minutes after the game read it, even if this window is closed by then
    $del = "Start-Sleep -Seconds 180; Remove-Item -LiteralPath '" + ($cfgFile -replace "'", "''") + "' -Force -ErrorAction SilentlyContinue"
    Start-Process -FilePath "powershell.exe" -WindowStyle Hidden -ArgumentList @("-NoProfile", "-Command", $del) | Out-Null
    Write-Log "host-and-play started for '$($p.name)' (light graphics: $light)"
    "the game is starting and will host '$(Remove-ColorCodes $p.hostname)' on port $($p.port)"
}

