                <StackPanel Grid.Column="2"><CheckBox x:Name="cbWhitelist" Content="Whitelist only (everyone else is refused)"/><TextBox x:Name="tbWhitelist" AcceptsReturn="True" Height="70" VerticalScrollBarVisibility="Auto"/></StackPanel>
              </Grid></GroupBox>
              <GroupBox Header="Discord webhook"><StackPanel>
                <TextBlock Foreground="{StaticResource Muted}" Text="Paste a channel webhook URL (Server Settings - Integrations - Webhooks). Stored encrypted on this PC for your Windows account only, never written to a log."/>
                <PasswordBox x:Name="pwWebhook"/>
                <WrapPanel>
                  <CheckBox x:Name="cbHookUp" Content="Server up   "/><CheckBox x:Name="cbHookDown" Content="Server down / crash   "/>
                  <CheckBox x:Name="cbHookJoin" Content="Player joined   "/><CheckBox x:Name="cbHookLeave" Content="Player left   "/>
                  <Button x:Name="btnHookTest" Content="Send a test message"/>
                </WrapPanel>
              </StackPanel></GroupBox>
            </StackPanel></ScrollViewer>
          </TabItem>
        </TabControl>
      </TabItem>

      <TabItem Header="Status">
        <Grid Margin="10">
          <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="2*"/><RowDefinition Height="3*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
          <StackPanel Orientation="Horizontal">
            <Button x:Name="btnStart2" Content="Start" Background="#FF4B5A2A"/>
            <Button x:Name="btnStop2" Content="Stop"/>
            <Button x:Name="btnRestart" Content="Restart"/>
            <Button x:Name="btnRecStart" Content="Record now" Margin="18,2,6,2"/>
            <Button x:Name="btnRecStop" Content="Stop recording"/>
            <Button x:Name="btnRecStatus" Content="Recording?"/>
            <TextBlock x:Name="txtRunState" Margin="10,0,0,0" FontWeight="SemiBold"/>
          </StackPanel>
          <DockPanel Grid.Row="1" Margin="0,8,0,4">
            <StackPanel DockPanel.Dock="Right" Margin="6,0,0,0">
              <Button x:Name="btnKick" Content="Kick"/>
              <Button x:Name="btnBan" Content="Ban IP"/>
            </StackPanel>
            <ListView x:Name="lvPlayers" Background="#FF14150F" Foreground="#FFE8E2D0" BorderBrush="{StaticResource Edge}">
              <ListView.View><GridView>
                <GridViewColumn Header="#" Width="40" DisplayMemberBinding="{Binding Num}"/>
                <GridViewColumn Header="Player" Width="260" DisplayMemberBinding="{Binding Name}"/>
                <GridViewColumn Header="Score" Width="70" DisplayMemberBinding="{Binding Score}"/>
                <GridViewColumn Header="Ping" Width="70" DisplayMemberBinding="{Binding Ping}"/>
                <GridViewColumn Header="Address" Width="180" DisplayMemberBinding="{Binding Address}"/>
              </GridView></ListView.View>
            </ListView>
          </DockPanel>
          <TextBox x:Name="tbConsole" Grid.Row="2" IsReadOnly="True" FontFamily="Consolas" FontSize="12" TextWrapping="NoWrap"
                   VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Auto" Margin="0,4"/>
          <DockPanel Grid.Row="3">
            <Button x:Name="btnRcon" Content="Send" DockPanel.Dock="Right" Margin="6,2,0,2"/>
            <TextBlock Text="Console command (rcon)  " DockPanel.Dock="Left"/>
            <TextBox x:Name="tbRcon"/>
          </DockPanel>
        </Grid>
      </TabItem>
    </TabControl>
  </DockPanel>
</Window>
'@
$win = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xaml))
$ui = @{}
foreach ($n in $xaml.SelectNodes("//*[@*[local-name()='Name']]")) { $nm = $n.GetAttribute("Name", "http://schemas.microsoft.com/winfx/2006/xaml"); if ($nm) { $ui[$nm] = $win.FindName($nm) } }

$script:Cat = $null
try { $script:Cat = Import-Catalogue } catch {
    [void][Windows.MessageBox]::Show("$_", "MOH Coop Server", "OK", "Error"); exit 1
}
$script:Inst = Get-Install
$script:Specs = $null
$script:Upload = 0.0
$script:Loading = $false
$script:Built = @{}

function Set-Status([string]$t) { $ui.txtStatusBar.Text = $t; Write-Log "status: $t" }
function Ask([string]$q, [string]$title = "MOH Coop Server") {
    if ($Snapshot) { return $false }
    [Windows.MessageBox]::Show($win, $q, $title, "YesNo", "Question") -eq "Yes"
}
function Tell([string]$t) { if (-not $Snapshot) { [void][Windows.MessageBox]::Show($win, $t, "MOH Coop Server", "OK", "Information") } }

# ---------------------------------------------------------------------------------------------------- colour preview
$script:QColors = @("#FF000000", "#FFFF0000", "#FF00FF00", "#FFFFFF00", "#FF0000FF", "#FF00FFFF", "#FFFF00FF", "#FFFFFFFF")
function Update-Preview {
    $tb = $ui.tbPreview; $tb.Inlines.Clear()
    $s = Get-CleanValue $ui.tbHostname.Text; $col = $script:QColors[7]; $i = 0; $run = ""
    $flush = { if ($run) { $r = New-Object Windows.Documents.Run $run; $r.Foreground = (New-Object Windows.Media.BrushConverter).ConvertFromString($col); $tb.Inlines.Add($r) } }
    while ($i -lt $s.Length) {
        if ($s[$i] -eq '^' -and $i + 1 -lt $s.Length -and [char]::IsLetterOrDigit($s[$i + 1])) {
            & $flush; $run = ""
            $col = $script:QColors[(([int][char]$s[$i + 1]) - 48) -band 7]; $i += 2; continue
        }
        $run += $s[$i]; $i++
    }
    & $flush
}

# ---------------------------------------------------------------------------------------------------- profile <-> ui
function Set-ModeHelp {
    if ($ui.rbListen.IsChecked) {
        $gp = if ($script:Specs) { @($script:Specs.Gpus) } else { @() }
        $ig = $gp.Count -gt 0 -and @($gp | Where-Object { -not $_.Integrated }).Count -eq 0
        $t = "Host and play starts the full game on this PC and hosts from inside it (a listen server). Your graphics card draws your game while the same process runs the server."
        if ($ig) { $t += " This PC has an integrated GPU only, so the lighter renderer (OpenGL 1) and the Low graphics preset are picked for you; your saved graphics settings change to those." }
        $t += " Rotation, auto-restart and the Discord join/leave messages need Dedicated."
        $ui.txtModeHelp.Text = $t
    } else {
        $ui.txtModeHelp.Text = "A dedicated server runs on its own, with no window and no graphics: it never uses your graphics card, integrated or dedicated, so it works the same on any PC. Play on it from this or another PC with the normal MOH Coop Trilogy shortcut (Multiplayer - join by IP, or the server list when Public)."
    }
}
function Set-MissionHelp {
    $ui.btnRotAdd.IsEnabled = $true
    if ($ui.rbCampaign.IsChecked) {
        $ui.txtMissionHelp.Text = "Starts at the campaign lobby ($($script:Cat['campaign']['lobby_map'])) and plays every mission in order, the same as Begin Full Campaign in the game."
        $ui.txtRightTitle.Text = "Start"; $ui.btnRotAdd.IsEnabled = $false
    } elseif ($ui.rbSingle.IsChecked) {
        $ui.txtMissionHelp.Text = "Starts on the mission picked on the left. When it is won the story carries on to the next mission, as in the game."
        $ui.txtRightTitle.Text = "Start mission"
    } else {
        $ui.txtMissionHelp.Text = "Plays the list on the right in order and starts again at the top. Needs Dedicated: the GUI's server watcher moves the server to the next entry whenever a mission ends."
        $ui.txtRightTitle.Text = "Rotation"
    }
}

function Load-ProfileToUi($p) {
    $script:Loading = $true
    $script:P = $p
    $script:Sec = Read-Secrets $p.name
    $ui.rbDedicated.IsChecked = ($p.mode -ne "listen"); $ui.rbListen.IsChecked = ($p.mode -eq "listen")
    $ui.tbHostname.Text = $p.hostname; $ui.pwJoin.Password = $script:Sec.password; $ui.pwRcon.Password = $script:Sec.rcon
    $ui.tbMaxPlayers.Text = "$($p.maxPlayers)"; $ui.tbPort.Text = "$($p.port)"; $ui.tbQueryPort.Text = "$($p.queryPort)"
    $ui.rbPublic.IsChecked = [bool]$p.public; $ui.rbLan.IsChecked = -not [bool]$p.public; $ui.cbMaster.IsChecked = [bool]$p.public
    $ui.rbCampaign.IsChecked = ($p.missionMode -eq "campaign"); $ui.rbSingle.IsChecked = ($p.missionMode -eq "single"); $ui.rbRotation.IsChecked = ($p.missionMode -eq "rotation")
    Fill-RightList
    $ui.cbPriority.SelectedItem = "$($p.priority)"
    $ui.cbAutoRestart.IsChecked = [bool]$p.autoRestart; $ui.cbDaily.IsChecked = [bool]$p.dailyRestart; $ui.tbDaily.Text = if ($p.dailyRestart) { $p.dailyRestart } else { "05:00" }
    $ui.cbStartup.IsChecked = [bool]$p.startWithWindows; $ui.rbStartWindow.IsChecked = ("$($p.startupMode)" -eq "window"); $ui.rbStartHidden.IsChecked = ("$($p.startupMode)" -ne "window")
    $ui.cbUpdate.IsChecked = [bool]$p.updateOnStart; $ui.tbLogDays.Text = "$($p.logKeepDays)"
    $ui.tbMotd.Text = $p.motd; $ui.tbMotdRepeat.Text = "$($p.motdRepeatMin)"
    $ui.cbRecord.IsChecked = [bool]$p.recordMatches; $ui.tbRecMax.Text = "$($p.recordMaxFiles)"; $ui.tbRecMaxMB.Text = "$($p.recordMaxMB)"
    $ui.tbRecFolder.Text = $p.recordFolder; $ui.tbRecFolderGB.Text = "$($p.recordFolderMaxGB)"; $ui.tbRecFolderDays.Text = "$($p.recordFolderMaxDays)"
    $ui.txtRecDir.Text = "The server writes its demos to $(Join-Path $script:Inst.Maintt 'demos') (auto_<map>_<date>...)."
    $ui.tbBans.Text = (@($p.bans) -join "`r`n"); $ui.tbWhitelist.Text = (@($p.whitelist) -join "`r`n"); $ui.cbWhitelist.IsChecked = [bool]$p.whitelistOn
    $ui.pwWebhook.Password = $script:Sec.webhook
    $ui.cbHookUp.IsChecked = [bool]$p.hookUp; $ui.cbHookDown.IsChecked = [bool]$p.hookDown; $ui.cbHookJoin.IsChecked = [bool]$p.hookJoin; $ui.cbHookLeave.IsChecked = [bool]$p.hookLeave
    Update-Preview; Set-ModeHelp; Set-MissionHelp
    Build-Affinity; Build-Tuning
    $script:Built = @{}; Build-Gameplay
    $ui.txtFirewall.Text = if (Test-FirewallRule $p) { "a rule for this profile exists" } else { "no rule for this profile yet" }
    $script:Loading = $false
}

function Read-UiToProfile {
    $p = $script:P
    $p.mode = if ($ui.rbListen.IsChecked) { "listen" } else { "dedicated" }
    $p.hostname = Get-CleanValue $ui.tbHostname.Text
    $n = 0; if ([int]::TryParse($ui.tbMaxPlayers.Text, [ref]$n) -and $n -ge 1 -and $n -le 64) { $p.maxPlayers = $n }
    if ([int]::TryParse($ui.tbPort.Text, [ref]$n) -and $n -ge 1024 -and $n -le 65535) { $p.port = $n }
    if ([int]::TryParse($ui.tbQueryPort.Text, [ref]$n) -and $n -ge 1024 -and $n -le 65535) { $p.queryPort = $n }
    $p.public = [bool]$ui.rbPublic.IsChecked
    $p.missionMode = if ($ui.rbCampaign.IsChecked) { "campaign" } elseif ($ui.rbRotation.IsChecked) { "rotation" } else { "single" }
    # the right-hand list still shows the mode it was filled for (a radio click reads it before refilling)
    if ($script:ListMode -eq "rotation") { $p.rotation = @($ui.lbRotation.Items | ForEach-Object { $_.Tag }) }
    elseif ($script:ListMode -eq "single" -and $ui.lbRotation.Items.Count) { $p.map = $ui.lbRotation.Items[0].Tag }
    $p.priority = "$($ui.cbPriority.SelectedItem)"
    $p.autoRestart = [bool]$ui.cbAutoRestart.IsChecked
    $p.dailyRestart = if ($ui.cbDaily.IsChecked -and $ui.tbDaily.Text -match '^\d{1,2}:\d{2}$') { $ui.tbDaily.Text } else { "" }
    $p.updateOnStart = [bool]$ui.cbUpdate.IsChecked
    if ([int]::TryParse($ui.tbLogDays.Text, [ref]$n) -and $n -ge 1) { $p.logKeepDays = $n }
    $p.motd = Get-CleanValue $ui.tbMotd.Text
    $p.recordMatches = [bool]$ui.cbRecord.IsChecked
    # 0 = keep all (no cap) in every recording limit; a server size cap below 50 MB is raised to 50
    if ([int]::TryParse($ui.tbRecMax.Text, [ref]$n) -and $n -ge 0) { $p.recordMaxFiles = $n }
    if ([int]::TryParse($ui.tbRecMaxMB.Text, [ref]$n) -and $n -ge 0) { $p.recordMaxMB = $(if ($n -eq 0) { 0 } else { [math]::Max(50, $n) }) }
    $p.recordFolder = $ui.tbRecFolder.Text.Trim()
    $dd = 0.0; if ([double]::TryParse($ui.tbRecFolderGB.Text, [ref]$dd) -and $dd -ge 0) { $p.recordFolderMaxGB = $dd }
    if ([int]::TryParse($ui.tbRecFolderDays.Text, [ref]$n) -and $n -ge 0) { $p.recordFolderMaxDays = $n }
    if ([int]::TryParse($ui.tbMotdRepeat.Text, [ref]$n) -and $n -ge 0) { $p.motdRepeatMin = $n }
    $p.bans = @($ui.tbBans.Text -split "[`r`n]+" | ForEach-Object { $_.Trim() } | Where-Object { $_ -match '^[0-9./]+$' })
    $p.whitelist = @($ui.tbWhitelist.Text -split "[`r`n]+" | ForEach-Object { $_.Trim() } | Where-Object { $_ -match '^[0-9./]+$' })
    $p.whitelistOn = [bool]$ui.cbWhitelist.IsChecked
    $p.hookUp = [bool]$ui.cbHookUp.IsChecked; $p.hookDown = [bool]$ui.cbHookDown.IsChecked; $p.hookJoin = [bool]$ui.cbHookJoin.IsChecked; $p.hookLeave = [bool]$ui.cbHookLeave.IsChecked
    $script:Sec.password = $ui.pwJoin.Password; $script:Sec.rcon = $ui.pwRcon.Password
    $wh = $ui.pwWebhook.Password.Trim()
    if ($wh -and -not (Test-WebhookUrl $wh)) { Set-Status "That is not a Discord webhook URL - it was not saved"; $wh = $script:Sec.webhook }
    $script:Sec.webhook = $wh
}

function Test-PortClash($p) {
    foreach ($n in Get-ProfileNames) {
        if ($n -eq $p.name) { continue }
        $o = Read-Profile $n
        if (-not (Test-Running $o)) { continue }
        if (@($o.port, $o.queryPort) | Where-Object { $_ -eq $p.port -or $_ -eq $p.queryPort }) { return $o.name }
    }
    ""
}

function Save-All {
    Read-UiToProfile
    if (-not $script:Sec.rcon) { $script:Sec.rcon = New-RandomPassword; $ui.pwRcon.Password = $script:Sec.rcon }
    Save-Profile $script:P; Save-Secrets $script:P.name $script:Sec
    $want = [bool]$ui.cbStartup.IsChecked
    $wantMode = if ($ui.rbStartWindow.IsChecked) { "window" } else { "hidden" }
    $oldMode = if ("$($script:P.startupMode)" -eq "window") { "window" } else { "hidden" }
    if ($want -ne [bool]$script:P.startWithWindows -or ($want -and $wantMode -ne $oldMode)) {
        $how = if ($wantMode -eq "window") { "opens this window and starts the server" } else { "starts the server hidden, with no window" }
        $verb = if (-not $want) { "Turn off" } elseif ([bool]$script:P.startWithWindows) { "Change" } else { "Turn on" }
        if (Ask ("{0} start-with-Windows for '{1}'?`n`nThis {2} an entry under your account's Run key (HKCU\...\Run). {3}Nothing else changes." -f $verb, $script:P.name, $(if ($want) { "writes" } else { "removes" }), $(if ($want) { "At sign-in it $how. " } else { "" }))) {
            $script:P.startupMode = $wantMode
            Set-StartWithWindows $script:P $want; $script:P.startWithWindows = $want; Save-Profile $script:P
        } else {
            $ui.cbStartup.IsChecked = [bool]$script:P.startWithWindows
            $ui.rbStartWindow.IsChecked = ($oldMode -eq "window"); $ui.rbStartHidden.IsChecked = ($oldMode -ne "window")
        }
    } elseif (-not $want) { $script:P.startupMode = $wantMode; Save-Profile $script:P }
    $gs = Get-GuiSettings; $gs.lastProfile = $script:P.name; Save-GuiSettings $gs
    Set-Status "Saved profile '$($script:P.name)'"
}

# ---------------------------------------------------------------------------------------------------- missions tab
function Fill-Missions {
    $tv = $ui.tvMissions; $tv.Items.Clear()
    $byo = Get-ByoMaps $script:Inst
    foreach ($b in $script:Cat["missions"]) {
        $maps = @($b["maps"] | Where-Object { -not $_["byo"] -or $byo.ContainsKey($_["map"]) })
        if (-not $maps.Count) { continue }        # an own-disc board shows only when this PC has converted that disc
        $ti = New-Object Windows.Controls.TreeViewItem
        $ti.Header = $b["title"] + $(if ($b["byo"]) { "   (your own disc)" } else { "" })
        $ti.Foreground = $ui.tbHostname.Foreground
        foreach ($m in $maps) {
            $c = New-Object Windows.Controls.TreeViewItem
            $c.Header = Get-MapLabel $m["spec"]; $c.Tag = $m["spec"]; $c.Foreground = $ui.tbHostname.Foreground
            $c.Add_MouseDoubleClick({ param($s, $e) Add-ToRight $s.Tag; $e.Handled = $true })
            [void]$ti.Items.Add($c)
        }
        [void]$tv.Items.Add($ti)
    }
}
function Get-MapLabel([string]$spec) {
    if ($spec -eq $script:Cat["campaign"]["lobby_map"]) { return "Campaign lobby  ($spec)" }
    foreach ($b in $script:Cat["missions"]) {
        foreach ($x in $b["maps"]) {
            if ($x["spec"] -eq $spec) {
                if ($x["title"] -eq $x["map"]) { return "{0}  ({1})" -f $b["title"], $x["map"] }
                return "{0}  ({1})" -f $x["title"], $x["map"]
            }
        }
    }
    $spec
}
function New-MapItem([string]$m) { $li = New-Object Windows.Controls.ListBoxItem; $li.Content = Get-MapLabel $m; $li.Tag = $m; $li }
function Fill-RightList {
    $ui.lbRotation.Items.Clear()
    $p = $script:P
    $script:ListMode = if ($ui.rbCampaign.IsChecked) { "campaign" } elseif ($ui.rbSingle.IsChecked) { "single" } else { "rotation" }
    if ($ui.rbCampaign.IsChecked) { [void]$ui.lbRotation.Items.Add((New-MapItem $script:Cat["campaign"]["lobby_map"])) }
    elseif ($ui.rbSingle.IsChecked) { [void]$ui.lbRotation.Items.Add((New-MapItem $p.map)) }
    else { foreach ($m in @($p.rotation)) { [void]$ui.lbRotation.Items.Add((New-MapItem $m)) } }
}
function Add-ToRight([string]$m) {
    if (-not $m -or -not (Test-MapSpec $m)) { return }
    if ($ui.rbSingle.IsChecked) { $ui.lbRotation.Items.Clear(); $script:P.map = $m }
    elseif ($ui.rbCampaign.IsChecked) { return }
    [void]$ui.lbRotation.Items.Add((New-MapItem $m))
}

# ---------------------------------------------------------------------------------------------------- setting rows
function Get-EffectiveValue($e) {
    $k = $e["name"]
    foreach ($x in $script:P.settings.Keys) { if ($x -ieq $k) { return $script:P.settings[$x] } }
    "$($e["default"])"
}
function Set-SettingValue($e, [string]$v) {
    $k = $e["name"]
    foreach ($x in @($script:P.settings.Keys)) { if ($x -ieq $k) { $script:P.settings.Remove($x) } }
    if ($v -ne "$($e["default"])") { $script:P.settings[$k] = $v }      # only changes are stored: unchanged = shipped
}
function New-SettingRow($e) {
    $g = New-Object Windows.Controls.Grid
    $g.Margin = "0,1,0,1"
    foreach ($w in @(300, 200, 170, 70)) { $cd = New-Object Windows.Controls.ColumnDefinition; $cd.Width = New-Object Windows.GridLength $w; [void]$g.ColumnDefinitions.Add($cd) }
    $cd = New-Object Windows.Controls.ColumnDefinition; $cd.Width = New-Object Windows.GridLength(1, "Star"); [void]$g.ColumnDefinitions.Add($cd)
    $lab = New-Object Windows.Controls.TextBlock
    $label = if ($e.ContainsKey("label") -and $e["label"]) { $e["label"] } else { $e["name"] }
    $lab.Text = $label; $lab.TextTrimming = "CharacterEllipsis"; $lab.TextWrapping = "NoWrap"
    $tip = $e["name"]; if ($e["description"]) { $tip += "`n" + $e["description"] }
    if ($e["unseeded"]) { $tip += "`n(no shipped default: when left empty the script decides)" }
    $lab.ToolTip = $tip
    [void]$g.Children.Add($lab)
    $val = Get-EffectiveValue $e
    $defTxt = New-Object Windows.Controls.TextBlock
    $defTxt.Foreground = $ui.txtStatusBar.Foreground; $defTxt.Margin = "8,0,0,0"; $defTxt.TextTrimming = "CharacterEllipsis"; $defTxt.TextWrapping = "NoWrap"
    $defTxt.Text = "default: " + $(if ("$($e["default"])" -eq "") { "(none)" } else { "$($e["default"])" })
    [Windows.Controls.Grid]::SetColumn($defTxt, 2)
    $reset = New-Object Windows.Controls.Button; $reset.Content = "Reset"; $reset.Padding = "6,1"
    [Windows.Controls.Grid]::SetColumn($reset, 3)
    if ($e["type"] -eq "bool") {
        $ed = New-Object Windows.Controls.CheckBox
        $ed.IsChecked = ($val -eq "1")
        $ed.Tag = $e
        $ed.Add_Click({ param($s, $a) Set-SettingValue $s.Tag $(if ($s.IsChecked) { "1" } else { "0" }); Update-GameplayCount })
        $reset.Tag = $ed
        $reset.Add_Click({ param($s, $a) $c = $s.Tag; $c.IsChecked = ("$($c.Tag["default"])" -eq "1"); Set-SettingValue $c.Tag "$($c.Tag["default"])"; Update-GameplayCount })
    } else {
        $ed = New-Object Windows.Controls.TextBox
        $ed.Text = $val; $ed.Tag = $e; $ed.Width = 190; $ed.HorizontalAlignment = "Left"
        $ed.Add_LostFocus({ param($s, $a)
            $e2 = $s.Tag; $v = Get-CleanValue $s.Text; $ok = $true
            if ($e2["type"] -eq "int") { $i = 0; $ok = [int]::TryParse($v, [ref]$i); if ($ok -and $e2.ContainsKey("min")) { $ok = $i -ge $e2["min"] -and $i -le $e2["max"] } }
            elseif ($e2["type"] -eq "float") { $f = 0.0; $ok = [double]::TryParse($v, [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$f) }
            if (-not $ok -and $v -ne "") {
                $rng = if ($e2.ContainsKey("min")) { " ($($e2["min"])-$($e2["max"]))" } else { "" }
                Set-Status "$($e2["name"]): '$v' is not a valid $($e2["type"])$rng - kept the old value"; $s.Text = Get-EffectiveValue $e2; return
            }
            Set-SettingValue $e2 $v; Update-GameplayCount })
        $reset.Tag = $ed
        $reset.Add_Click({ param($s, $a) $t = $s.Tag; $t.Text = "$($t.Tag["default"])"; Set-SettingValue $t.Tag "$($t.Tag["default"])"; Update-GameplayCount })
    }
    [Windows.Controls.Grid]::SetColumn($ed, 1)
    [void]$g.Children.Add($ed); [void]$g.Children.Add($defTxt); [void]$g.Children.Add($reset)
    $d = New-Object Windows.Controls.TextBlock
    $d.Text = if ($e["description"]) { $e["description"] } elseif ($e.ContainsKey("label")) { $e["name"] } else { "" }
    $d.TextTrimming = "CharacterEllipsis"; $d.TextWrapping = "NoWrap"; $d.Foreground = $ui.txtStatusBar.Foreground; $d.Margin = "8,0,0,0"; $d.ToolTip = $tip
    [Windows.Controls.Grid]::SetColumn($d, 4); [void]$g.Children.Add($d)
    $g
}
function Get-GameplayEntries {
    @($script:Cat["settings"] | Where-Object { $_["page"] -eq "gameplay" })
}
function Update-GameplayCount {
    $n = 0; foreach ($k in $script:P.settings.Keys) { $n++ }
    $ui.txtGameplayCount.Text = "$n changed from the shipped defaults"
}
function Build-Gameplay {
    $sp = $ui.spGameplay; $sp.Children.Clear()
    $ui.txtGameplayHelp.Text = "Every server-side setting of the mod, read from its generated catalogue ($(@(Get-GameplayEntries).Count) settings). Only the ones you change are written to the server; everything else keeps the shipped default. Hover a name for what it does."
    $q = $ui.tbSearch.Text.Trim(); $changedOnly = [bool]$ui.cbChangedOnly.IsChecked
    $entries = Get-GameplayEntries
    if ($q -or $changedOnly) {
        $hits = @($entries | Where-Object {
            $ok = $true
            if ($q) { $ok = ($_["name"] -like "*$q*") -or ("$($_["description"])" -like "*$q*") -or ("$($_["label"])" -like "*$q*") }
            if ($ok -and $changedOnly) { $nm = $_["name"]; $ok = [bool]($script:P.settings.Keys | Where-Object { $_ -ieq $nm }) }
            $ok })
        $lab = New-Object Windows.Controls.TextBlock; $lab.Text = "$($hits.Count) match(es)$(if ($hits.Count -gt 300) { ', first 300 shown' })"; $lab.Foreground = $ui.txtStatusBar.Foreground
        [void]$sp.Children.Add($lab)
        foreach ($e in ($hits | Select-Object -First 300)) { [void]$sp.Children.Add((New-SettingRow $e)) }
    } else {
        foreach ($c in $script:Cat["categories"]) {
            $list = @($entries | Where-Object { $_["category"] -eq $c })
            if (-not $list.Count) { continue }
            $ex = New-Object Windows.Controls.Expander
            $ex.Header = "$c  ($($list.Count))"; $ex.Tag = $c
            $ex.IsExpanded = ($c -eq "Players and lives")
            $ex.Add_Expanded({ param($s, $a) Fill-Expander $s })
            [void]$sp.Children.Add($ex)
            if ($ex.IsExpanded) { Fill-Expander $ex }
        }
    }
    Update-GameplayCount
}
function Fill-Expander($ex) {
    if ($ex.Content) { return }
    $inner = New-Object Windows.Controls.StackPanel; $inner.Margin = "18,2,0,6"
    foreach ($e in @(Get-GameplayEntries | Where-Object { $_["category"] -eq $ex.Tag } | Sort-Object { if ($_.ContainsKey("label")) { 0 } else { 1 } }, { $_["name"] })) {
        [void]$inner.Children.Add((New-SettingRow $e))
    }
    $ex.Content = $inner
}
function Build-Tuning {
    $sp = $ui.spTuning; $sp.Children.Clear()
    $h = New-Object Windows.Controls.TextBlock
    $h.Text = "How fast the server runs and how much it may send. The shipped values are what the public coop servers use; change them only for a reason. Memory: maxentities is the entity pool every map shares."
    $h.Foreground = $ui.txtStatusBar.Foreground; $h.Margin = "0,0,0,8"
    [void]$sp.Children.Add($h)
    foreach ($e in @($script:Cat["settings"] | Where-Object { $_["page"] -eq "tuning" } | Sort-Object { $_["name"] })) { [void]$sp.Children.Add((New-SettingRow $e)) }
}

# ---------------------------------------------------------------------------------------------------- CPU / specs
function Build-Affinity {
    $wp = $ui.wpAffinity; $wp.Children.Clear()
    if (-not $script:Specs) { return }
    $sel = @($script:P.affinity)
    foreach ($c in $script:Specs.CoreList) {
        $kind = if (-not $script:Specs.Hybrid) { "core" } elseif ($c.Efficiency -eq $script:Specs.MaxEff) { "P-core" } else { "E-core" }
        $box = New-Object Windows.Controls.Border; $box.BorderBrush = $ui.tbHostname.BorderBrush; $box.BorderThickness = 1; $box.Margin = "0,0,6,6"; $box.Padding = "6,3"
        $st = New-Object Windows.Controls.StackPanel
        $hd = New-Object Windows.Controls.TextBlock; $hd.Text = "$kind $($c.Index)"; $hd.Foreground = $ui.txtStatusBar.Foreground; $hd.FontSize = 11
        [void]$st.Children.Add($hd)
        foreach ($t in $c.Threads) {
            $cb = New-Object Windows.Controls.CheckBox
            $l = if ($script:Specs.Load.ContainsKey($t)) { " $($script:Specs.Load[$t])%" } else { "" }
            $cb.Content = "thread $t$l"; $cb.Tag = $t; $cb.IsChecked = ($sel -contains $t); $cb.Margin = "0,1"
            $cb.ToolTip = if ($c.Threads.Count -gt 1) { "SMT siblings on this core: $($c.Threads -join ', ')" } else { "no SMT sibling" }
            $cb.Add_Click({ param($s, $a) Update-AffinityFromUi })
            [void]$st.Children.Add($cb)
        }
        $box.Child = $st; [void]$wp.Children.Add($box)
    }
    $rec = Get-RecommendedThread $script:Specs
    $ui.txtAffRec.Text = if ($rec) { "Recommended: thread $($rec.Thread) (core $($rec.Core)$(if ($script:Specs.Hybrid) { ', a P-core' })$(if (@($rec.Siblings).Count) { "; its SMT sibling $(@($rec.Siblings) -join ',') is left for Windows" }))" } else { "" }
    $ui.txtAffHelp.Text = "Which CPU thread the dedicated server runs on. The server does its work on one thread, so one fast, quiet thread beats many. None ticked = Windows decides. Load % is a snapshot from 'Scan again' on PC Specs."
}
function Update-AffinityFromUi {
    $sel = @()
    foreach ($b in $ui.wpAffinity.Children) { foreach ($cb in $b.Child.Children) { if ($cb -is [Windows.Controls.CheckBox] -and $cb.IsChecked) { $sel += [int]$cb.Tag } } }
    $script:P.affinity = $sel
}
function Show-Specs {
    $s = $script:Specs
    if (-not $s) { return }
    $L = @("Model        $($s.CpuName)", "Cores        $($s.Cores)  /  threads $($s.Threads)   (max $($s.MaxMHz) MHz)")
    if ($s.Hybrid) { $L += "Hybrid       yes: $($s.PCores) P-cores (performance), $($s.ECores) E-cores (efficiency)" } else { $L += "Hybrid       no (all cores are the same kind)" }
    $smt = @($s.CoreList | Where-Object { $_.Threads.Count -gt 1 })
    $L += "SMT          $(if ($smt.Count) { 'on - sibling threads per core:' } else { 'off / not present' })"
    foreach ($c in $s.CoreList) {
        $kind = if (-not $s.Hybrid) { "core" } elseif ($c.Efficiency -eq $s.MaxEff) { "P" } else { "E" }
        $ld = @($c.Threads | ForEach-Object { if ($s.Load.ContainsKey($_)) { "$($s.Load[$_])%" } else { "-" } }) -join " "
        $L += ("   {0,-4} {1,2}: threads {2,-10} load {3}" -f $kind, $c.Index, ($c.Threads -join ","), $ld)
    }
    $ui.txtCpu.Text = $L -join "`n"
    $sysL = @("RAM          $($s.RamGB) GB  ($($s.FreeRamGB) GB free)")
    foreach ($g in $s.Gpus) { $sysL += ("GPU          {0}  -  {1}{2}" -f $g.Name, $(if ($g.Integrated) { "INTEGRATED" } else { "dedicated" }), $(if ($g.VramMB -gt 0) { ", $($g.VramMB) MB" } else { "" })) }
    if (-not @($s.Gpus).Count) { $sysL += "GPU          none detected" }
    $sysL += "Disk         $($s.DiskFreeGB) GB free on $($s.DiskName) (the game's drive)"
    $sysL += "Upload       $(if ($script:Upload -gt 0) { "$($script:Upload) Mbit/s (tested)" } else { 'not tested' })"
    $ui.txtSys.Text = $sysL -join "`n"
    $sg = Get-SuggestedPlayers $s $script:Upload -HostAndPlay:([bool]$ui.rbListen.IsChecked)
    $ig = @($s.Gpus | Where-Object { -not $_.Integrated }).Count -eq 0
    $t = "Suggested max players: $($sg.Players)  ($($sg.Why)). The campaign is balanced for up to 4 players and the public coop servers run 4."
    $t += "`n`nDedicated server: uses no graphics card at all, so an integrated GPU is fine for hosting."
    if ($ig) { $t += "`nHost and play: this PC has only an integrated GPU, so host-and-play uses the lighter OpenGL 1 renderer and the Low preset automatically." }
    $ui.txtSuggestion.Text = $t
    $ui.txtSuggest.Text = "suggested for this PC: $($sg.Players)"
}
function Invoke-Scan {
    Set-Status "Scanning this PC..."
    $script:Specs = Get-PcSpecs
    Show-Specs; Build-Affinity; Set-ModeHelp
    Set-Status "PC scanned"
}

# ---------------------------------------------------------------------------------------------------- status tab
function Get-LatestLog($p) {
    $s = Get-State $p
    if ($s -and $s.log -and (Test-Path -LiteralPath $s.log)) { return $s.log }
    $null
}
function Read-Tail([string]$f, [int]$maxBytes = 48KB) {
    try {
        $fs = [IO.File]::Open($f, 'Open', 'Read', 'ReadWrite')
        try {
            $len = $fs.Length; $start = [math]::Max(0, $len - $maxBytes); [void]$fs.Seek($start, 'Begin')
            $b = New-Object byte[] ($len - $start); $n = $fs.Read($b, 0, $b.Length)
            [Text.Encoding]::GetEncoding(28591).GetString($b, 0, $n)
        } finally { $fs.Close() }
    } catch { "" }
}
function Update-StatusTab {
    $p = $script:P
    if (-not $p) { return }
    $running = Test-Running $p
    $s = Get-State $p
    if ($p.mode -eq "listen") {
        $st = Get-ServerStatus $p.port
        $ui.txtRunState.Text = if ($st) { "Host and play: up on port $($p.port), map $($st.Info['mapname'])" } else { "Host and play: not running" }
        if ($st) { $ui.lvPlayers.ItemsSource = @($st.Players) }
        return
    }
    if ($running -and $s) {
        $ui.txtRunState.Text = "{0} - map {1} - {2} player(s) - restarts {3} - server pid {4}" -f $s.state, $s.map, $s.players, $s.restarts, $s.serverPid
        # the supervisor polls rcon status every 10 s; the window reads its state file instead of adding rcon traffic
        $ui.lvPlayers.ItemsSource = @($s.playerList | Where-Object { $_ })
        $lg = Get-LatestLog $p
        if ($lg) {
            $t = Read-Tail $lg
            if ($t.Length -ne $ui.tbConsole.Text.Length) { $ui.tbConsole.Text = $t; $ui.tbConsole.ScrollToEnd() }
        }
    } else {
        $ui.txtRunState.Text = "Stopped"
        $ui.lvPlayers.ItemsSource = $null
    }
    $ui.btnStart.IsEnabled = -not $running; $ui.btnStart2.IsEnabled = -not $running
}

function Start-Current {
    Save-All
    $p = $script:P
    $clash = Test-PortClash $p
    if ($clash) { Tell "Profile '$clash' is already running on port $($p.port) or $($p.queryPort). Give this profile other ports (Server tab)."; return }
    if ($p.mode -eq "listen") {
        $gp = if ($script:Specs) { @($script:Specs.Gpus) } else { @(Get-GpuInfo) }
        $light = $gp.Count -gt 0 -and @($gp | Where-Object { -not $_.Integrated }).Count -eq 0
        if (-not (Test-Path -LiteralPath $script:Inst.Client)) { Tell "openmohaa.exe was not found in $($script:Inst.Root)."; return }
        Set-Status (Start-ListenServer $p $script:Sec $script:Cat $script:Inst $light)
        return
    }
    if (-not (Test-Path -LiteralPath $script:Inst.Ded)) { Tell "omohaaded.exe was not found in $($script:Inst.Root). Run the MOH Coop Trilogy shortcut once so the updater brings it."; return }
    if ($p.missionMode -eq "rotation" -and -not @($p.rotation).Count) { Tell "The rotation is empty: add missions on the Missions tab."; return }
    if (Test-Running $p) { Set-Status "Already running"; return }
    [void](Start-Supervisor $p)
    Set-Status "Starting '$($p.name)' on port $($p.port)..."
    $ui.tabs.SelectedIndex = 5
}
function Stop-Current {
    $p = $script:P
    if ($p.mode -eq "listen") {
        if (Get-ServerStatus $p.port) { [void](Invoke-Rcon $p.port $script:Sec.rcon "killserver"); Set-Status "Asked the game to stop hosting" }
        return
    }
    if (Test-Running $p) { Stop-Supervisor $p; Set-Status "Stopping '$($p.name)'..." } else { Set-Status "Not running" }
}

