    if (-not (Ask "Delete profile '$($p.name)'? Its settings and stored passwords are removed (its logs are kept).")) { return }
    if ($p.startWithWindows) { Set-StartWithWindows $p $false }
    Remove-Item -LiteralPath (Join-Path $DataDir "profiles\$($p.name).json"), (Join-Path $DataDir "profiles\$($p.name).secret") -Force -ErrorAction SilentlyContinue
    $n = @(Get-ProfileNames)[0]; Refresh-ProfileList $n; Select-Profile $n })

# ---------------------------------------------------------------------------------------------------- start up
if (-not @(Get-ProfileNames).Count) { Save-Profile (New-Profile "Default") }
# a generated cfg left behind (a crash before the supervisor or the timer removed it) still holds passwords
Get-ChildItem -LiteralPath (Join-Path $script:Inst.Maintt "hzm_servergui") -Filter "*.cfg" -File -ErrorAction SilentlyContinue |
    Where-Object { $_.LastWriteTime -lt (Get-Date).AddMinutes(-10) } | ForEach-Object {
        $tag = $_.BaseName -replace '_listen$', ''
        if (-not (Get-ProfileNames | Where-Object { (Get-ProfileTag ([pscustomobject]@{ name = $_ })) -eq $tag } | Where-Object { Test-Running (Read-Profile $_) })) {
            Remove-Item -LiteralPath $_.FullName -Force -ErrorAction SilentlyContinue
        }
    }
$gs = Get-GuiSettings
$first = if (@(Get-ProfileNames) -contains $gs.lastProfile) { $gs.lastProfile } else { @(Get-ProfileNames)[0] }
if ($StartProfile) {
    if (@(Get-ProfileNames) -contains $StartProfile) { $first = $StartProfile }
    else { Write-Log "-StartProfile '$StartProfile': no such profile - the window opens without starting a server"; $StartProfile = "" }
}
$script:Specs = Get-PcSpecs
$ui.txtInstall.Text = "Game files: $($script:Inst.Root)`nGame data (base): $($script:Inst.Base)`nMod files (home): $($script:Inst.Home)`nCatalogue: $($script:Cat['_path']) ($(@($script:Cat['settings']).Count) settings)$(if ($DryRun) { "`nDRY RUN: firewall, UPnP and start-with-Windows are logged, never executed" })"
Refresh-ProfileList $first
Load-ProfileToUi (Read-Profile $first)
Fill-Missions
Show-Specs
$ui.txtIps.Text = "This PC on your network: $(Get-LocalIp)"

$timer = New-Object Windows.Threading.DispatcherTimer
$timer.Interval = [TimeSpan]::FromSeconds(2)
$timer.Add_Tick({ if ($ui.tabs.SelectedIndex -eq 5) { Update-StatusTab } })
$timer.Start()
$win.Add_Closing({ $timer.Stop() })

if ($Snapshot) {
    # QA: render every tab without the window ever being activated, then report text that does not fit
    if (-not (Test-Path -LiteralPath $Snapshot)) { New-Item -ItemType Directory -Force -Path $Snapshot | Out-Null }
    $win.ShowActivated = $false; $win.ShowInTaskbar = $false; $win.WindowStartupLocation = "Manual"
    $win.Left = -20000; $win.Top = -20000; $win.Width = $SnapshotWidth; $win.Height = $SnapshotHeight
    $win.Show()
    $scale = $SnapshotDpi / 96.0
    $report = New-Object System.Collections.Generic.List[string]
    function Get-Clipped($root) {
        $q = New-Object System.Collections.Generic.Queue[object]; $q.Enqueue($root)
        while ($q.Count) {
            $v = $q.Dequeue()
            if ($v -is [Windows.Controls.TextBlock] -and $v.IsVisible -and $v.ActualWidth -gt 0 -and $v.Text) {
                $f = New-Object Windows.Media.FormattedText($v.Text, [Globalization.CultureInfo]::CurrentUICulture, "LeftToRight",
                    (New-Object Windows.Media.Typeface($v.FontFamily, $v.FontStyle, $v.FontWeight, $v.FontStretch)), $v.FontSize, [Windows.Media.Brushes]::White,
                    $null, [Windows.Media.TextFormattingMode]::Display, $scale)
                $nowrap = ($v.TextWrapping -eq "NoWrap") -or ($v.Text -notmatch '\s')
                if ($nowrap -and $f.WidthIncludingTrailingWhitespace -gt $v.ActualWidth + 3 -and $v.TextTrimming -eq "None") { $report.Add("CLIPPED '$($v.Text)' needs $([int]$f.Width) has $([int]$v.ActualWidth)") }
            }
            for ($i = 0; $i -lt [Windows.Media.VisualTreeHelper]::GetChildrenCount($v); $i++) { $q.Enqueue([Windows.Media.VisualTreeHelper]::GetChild($v, $i)) }
        }
    }
    function Save-Shot([string]$name) {
        $win.UpdateLayout()
        $win.Dispatcher.Invoke([action] {}, [Windows.Threading.DispatcherPriority]::ApplicationIdle)
        $root = $win.Content
        $w = [int]($root.ActualWidth * $scale); $h = [int]($root.ActualHeight * $scale)
        $bmp = New-Object Windows.Media.Imaging.RenderTargetBitmap($w, $h, $SnapshotDpi, $SnapshotDpi, [Windows.Media.PixelFormats]::Pbgra32)
        $bg = New-Object Windows.Media.DrawingVisual
        $dc = $bg.RenderOpen(); $dc.DrawRectangle($win.Background, $null, (New-Object Windows.Rect(0, 0, $root.ActualWidth, $root.ActualHeight))); $dc.Close()
        $bmp.Render($bg); $bmp.Render($root)
        $enc = New-Object Windows.Media.Imaging.PngBitmapEncoder; $enc.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($bmp))
        $fs = [IO.File]::Create((Join-Path $Snapshot "$name.png")); $enc.Save($fs); $fs.Close()
        $before = $report.Count; Get-Clipped $root
        for ($i = $before; $i -lt $report.Count; $i++) { $report[$i] = "$name : " + $report[$i] }
    }
    $names = @("1_server", "2_missions", "3_gameplay", "4_pcspecs", "5_advanced", "6_status")
    for ($t = 0; $t -lt 6; $t++) {
        $ui.tabs.SelectedIndex = $t
        if ($t -eq 1) { foreach ($it in $ui.tvMissions.Items) { $it.IsExpanded = ($ui.tvMissions.Items.IndexOf($it) -lt 2) } }
        if ($t -eq 5) { $ui.tbConsole.Text = (Read-Tail ((Get-ChildItem -LiteralPath (Join-Path $DataDir "logs") -Recurse -Filter "server_*.log" -ErrorAction SilentlyContinue | Sort-Object LastWriteTime | Select-Object -Last 1).FullName) 6KB); Update-StatusTab }
        Save-Shot $names[$t]
        if ($t -eq 2) { $ui.tbSearch.Text = "lives"; Save-Shot "3b_gameplay_search"; $ui.tbSearch.Text = "" }
        if ($t -eq 4) {
            $an = @("5a_adv_cpu", "5b_adv_tuning", "5c_adv_network", "5d_adv_reliability", "5f_adv_recording", "5e_adv_admin")
            for ($a = 0; $a -lt 6; $a++) { $ui.advTabs.SelectedIndex = $a; Save-Shot $an[$a] }
        }
    }
    try { Read-UiToProfile } catch { $report.Add("ERROR Read-UiToProfile: $_") }    # the Save path, minus the write
    [IO.File]::WriteAllLines((Join-Path $Snapshot "clipped.txt"), [string[]]@($report))
    "snapshots: $Snapshot  clipped: $($report.Count)"
    $win.Close()
    exit 0
}

if ($StartProfile) {
    # start-with-Windows, "open this window" choice: the window first, then the same Start button path as a click
    $win.Add_ContentRendered({
        Write-Log "-StartProfile '$StartProfile': starting its server"
        try { Start-Current } catch { Write-Log "-StartProfile start failed: $_" }
        $ui.tabs.SelectedIndex = 5
    })
}
[void]$win.ShowDialog()
